cd /home/runner/work/Newroz/Newroz && mkdir -p public/fonts && node --input-type=module <<'EOF'
import {readFileSync, writeFileSync} from 'fs';
const css=readFileSync('/tmp/fonts2.css','utf8');
const blocks=css.split('/* ').slice(1).map(s=>'/* '+s);
let out=''; let n=0;
for(const b of blocks){
  const subset=b.match(/^\/\* ([a-z-]+) \*\//)?.[1];
  if(!['arabic','latin'].includes(subset)) continue;
  const fam=b.match(/font-family: '([^']+)'/)?.[1];
  const weight=b.match(/font-weight: ([\d ]+);/)?.[1];
  const url=b.match(/url\((https:[^)]+)\)/)?.[1];
  if(!fam||!url) continue;
  const file=`${fam.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-${weight.replace(' ','-')}-${subset}.woff2`;
  const res=await fetch(url); if(!res.ok) throw new Error('fetch '+url);
  writeFileSync('public/fonts/'+file, Buffer.from(await res.arrayBuffer()));
  const unicode=b.match(/unicode-range: ([^;]+);/)?.[1];
  out+=`@font-face{font-family:'${fam}';font-style:normal;font-weight:${weight};font-display:swap;src:url('/fonts/${file}') format('woff2');${unicode?`unicode-range:${unicode};`:''}}\n`;
  n++;
}
writeFileSync('src/styles/fonts.css',out);
console.log('downloaded',n);
EOF
