        dir="ltr"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(Number(e.target.value))}
        style={{ '--fill': `${pct}%` } as React.CSSProperties}
        aria-label={label}
      />
      <div className="range-field__meta">
        {hint && <span>{hint}</span>}
        {defaultValue != null && value !== defaultValue && (
