export function Modal({
  open,
  onClose,
  title,
  subtitle,
  children,
  footer,
  size = 'md',
  sheetOnMobile = true,
}: {
  open: boolean
  onClose: () => void
  title: string
  subtitle?: string
  children: ReactNode
  footer?: ReactNode
  size?: 'sm' | 'md' | 'lg'
  sheetOnMobile?: boolean
}) {
  useEffect(() => {
    if (!open) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    document.addEventListener('keydown', onKey)
    const prev = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => {
      document.removeEventListener('keydown', onKey)
      document.body.style.overflow = prev
    }
  }, [open, onClose])

  if (!open) return null
  return (
    <div className="modal-layer" role="presentation">
      <button type="button" className="modal-backdrop" aria-label="إغلاق" onClick={onClose} />
      <div
        className={`modal glass modal--${size} ${sheetOnMobile ? 'modal--sheet' : ''}`}
        role="dialog"
        aria-modal="true"
        aria-label={title}
      >
        <div className="modal__handle" aria-hidden />
        <header className="modal__header">
          <div>
            <h2 className="modal__title">{title}</h2>
            {subtitle && <p className="modal__subtitle">{subtitle}</p>}
          </div>
          <IconButton label="إغلاق" onClick={onClose}>
            <X size={18} />
          </IconButton>
        </header>
        <div className="modal__body">{children}</div>
        {footer && <footer className="modal__footer">{footer}</footer>}
      </div>
    </div>
  )
}

import { useEffect, useRef } from 'react'
import { geoOrthographic, geoPath, geoGraticule10, geoDistance } from 'd3-geo'
import { feature } from 'topojson-client'
import landTopoRaw from 'world-atlas/land-110m.json'
import countriesTopoRaw from 'world-atlas/countries-110m.json'
import type { Feature, FeatureCollection, Geometry } from 'geojson'
import type { Topology, GeometryCollection } from 'topojson-specification'

const landTopo = landTopoRaw as unknown as Topology<{ land: GeometryCollection }>
const countriesTopo = countriesTopoRaw as unknown as Topology<{ countries: GeometryCollection }>

const LAND = feature(landTopo, landTopo.objects.land) as Feature<Geometry> | FeatureCollection<Geometry>
const COUNTRIES = feature(
  countriesTopo,
  countriesTopo.objects.countries,
) as FeatureCollection<Geometry>

const CITIES: { name: string; coords: [number, number]; accent?: boolean }[] = [
  { name: 'الرياض', coords: [46.7, 24.7], accent: true },
  { name: 'القاهرة', coords: [31.2, 30], accent: true },
  { name: 'إسطنبول', coords: [29, 41] },
  { name: 'لندن', coords: [-0.1, 51.5] },
  { name: 'نيويورك', coords: [-74, 40.7] },
  { name: 'طوكيو', coords: [139.7, 35.7] },
  { name: 'نيروبي', coords: [36.8, -1.3] },
  { name: 'ساو باولو', coords: [-46.6, -23.5] },
  { name: 'دلهي', coords: [77.2, 28.6] },
]

function seededRandom(seed: number) {
  let s = seed
  return () => {
    s = (s * 9301 + 49297) % 233280
    return s / 233280
  }
}

export function WorldGlobe({
  className = '',
  motionEnabled = true,
  interactive = true,
}: {
  className?: string
  motionEnabled?: boolean
  interactive?: boolean
}) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null)
  const frameRef = useRef<number>(0)
  const rotationRef = useRef<[number, number]>([-30, -18])
  const dragRef = useRef<{ active: boolean; x: number; y: number; moved: number }>({
    active: false,
    x: 0,
    y: 0,
    moved: 0,
  })
  const idleRef = useRef(0)
  const visibleRef = useRef(true)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    let width = 0
    let height = 0
    let dpr = 1
    const stars = Array.from({ length: 180 }, (_, i) => {
      const rand = seededRandom(91 + i * 37)
      return {
        x: rand(),
        y: rand(),
        r: 0.4 + rand() * 1.3,
        a: 0.08 + rand() * 0.5,
        phase: rand() * Math.PI * 2,
      }
    })
    const projection = geoOrthographic().clipAngle(90).precision(0.6)
    const path = geoPath(projection, ctx)
    const graticule = geoGraticule10()

    const resize = () => {
      const rect = canvas.getBoundingClientRect()
      dpr = Math.min(window.devicePixelRatio || 1, 1.8)
      width = Math.max(1, rect.width)
      height = Math.max(1, rect.height)
      canvas.width = Math.round(width * dpr)
      canvas.height = Math.round(height * dpr)
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    }

    let lastFrame = 0
    const draw = (time: number) => {
      frameRef.current = requestAnimationFrame(draw)
      if (!visibleRef.current) return
      if (time - lastFrame < 30) return
      const delta = lastFrame ? Math.min(60, time - lastFrame) : 16
      lastFrame = time

      if (motionEnabled && !dragRef.current.active && time - idleRef.current > 2200) {
        rotationRef.current[0] += delta * 0.0028
      }

      const [lambda, phi] = rotationRef.current
      projection
        .scale(Math.min(width, height) * 0.405)
        .translate([width * 0.5, height * 0.5])
        .rotate([lambda, phi])
      const radius = projection.scale()
      const cx = width * 0.5
      const cy = height * 0.5

      ctx.clearRect(0, 0, width, height)

      // Star field
      for (const star of stars) {
        const twinkle = motionEnabled ? 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(time * 0.0006 + star.phase)) : 1
        ctx.globalAlpha = star.a * twinkle
        ctx.fillStyle = '#d9e6d9'
        ctx.beginPath()
        ctx.arc(star.x * width, star.y * height, star.r, 0, Math.PI * 2)
        ctx.fill()
      }
      ctx.globalAlpha = 1

      // Orbital ring
      ctx.save()
      ctx.translate(cx, cy)
      ctx.rotate(-0.28)
      ctx.beginPath()
      ctx.ellipse(0, 0, radius * 1.34, radius * 0.36, 0, 0, Math.PI * 2)
      ctx.strokeStyle = 'rgba(196,164,112,0.16)'
      ctx.lineWidth = 1
      ctx.stroke()
      ctx.beginPath()
      ctx.ellipse(0, 0, radius * 1.5, radius * 0.44, 0, 0, Math.PI * 2)
      ctx.strokeStyle = 'rgba(196,164,112,0.06)'
      ctx.stroke()
      ctx.restore()

      // Atmosphere
      const glow = ctx.createRadialGradient(cx, cy, radius * 0.86, cx, cy, radius * 1.26)
      glow.addColorStop(0, 'rgba(89,140,112,0.0)')
      glow.addColorStop(0.36, 'rgba(98,150,121,0.15)')
      glow.addColorStop(0.62, 'rgba(168,180,143,0.06)')
      glow.addColorStop(1, 'rgba(20,46,35,0)')
      ctx.fillStyle = glow
      ctx.beginPath()
      ctx.arc(cx, cy, radius * 1.26, 0, Math.PI * 2)
      ctx.fill()

      // Ocean sphere
      const ocean = ctx.createRadialGradient(
        cx - radius * 0.4,
        cy - radius * 0.45,
        radius * 0.08,
        cx,
        cy,
        radius,
      )
      ocean.addColorStop(0, '#2b5b47')
      ocean.addColorStop(0.45, '#1b4133')
      ocean.addColorStop(0.8, '#102d23')
      ocean.addColorStop(1, '#081b14')
      ctx.beginPath()
      ctx.arc(cx, cy, radius, 0, Math.PI * 2)
      ctx.fillStyle = ocean
      ctx.fill()

      // Graticule
      ctx.beginPath()
      path(graticule)
      ctx.strokeStyle = 'rgba(190,209,190,0.12)'
      ctx.lineWidth = 0.6
      ctx.stroke()

      // Countries
      for (const country of COUNTRIES.features) {
        ctx.beginPath()
        path(country)
        const id = Number(country.id ?? 0)
        const shade = 0.82 + ((id * 37) % 17) / 100
        ctx.fillStyle = `rgba(43,82,63,${0.55 * shade})`
        ctx.fill()
        ctx.strokeStyle = 'rgba(120,157,130,0.24)'
        ctx.lineWidth = 0.4
        ctx.stroke()
      }

      // Land silhouette highlight
      ctx.beginPath()
      path(LAND)
      ctx.fillStyle = 'rgba(120,164,133,0.06)'
      ctx.fill()

      // Daylight and night shading clipped to sphere
      ctx.save()
      ctx.beginPath()
      ctx.arc(cx, cy, radius, 0, Math.PI * 2)
      ctx.clip()
      const light = ctx.createRadialGradient(
        cx - radius * 0.48,
        cy - radius * 0.52,
        radius * 0.05,
        cx - radius * 0.2,
        cy - radius * 0.2,
        radius * 1.5,
      )
      light.addColorStop(0, 'rgba(246,235,207,0.2)')
      light.addColorStop(0.42, 'rgba(246,235,207,0.03)')
      light.addColorStop(1, 'rgba(0,0,0,0)')
      ctx.fillStyle = light
      ctx.fillRect(cx - radius, cy - radius, radius * 2, radius * 2)
      const night = ctx.createRadialGradient(
        cx + radius * 0.65,
        cy + radius * 0.7,
        radius * 0.05,
        cx + radius * 0.4,
        cy + radius * 0.4,
        radius * 1.2,
      )
      night.addColorStop(0, 'rgba(3,10,7,0.55)')
      night.addColorStop(1, 'rgba(3,10,7,0)')
      ctx.fillStyle = night
      ctx.fillRect(cx - radius, cy - radius, radius * 2, radius * 2)

      // Weather haze
      const hazeTime = motionEnabled ? time * 0.00002 : 0
      for (let i = 0; i < 3; i++) {
        const hx = cx - radius * 0.6 + ((i * 0.7 + hazeTime) % 1.6) * radius
        const hy = cy - radius * 0.45 + i * radius * 0.42
        const haze = ctx.createRadialGradient(hx, hy, 0, hx, hy, radius * 0.62)
        haze.addColorStop(0, 'rgba(226,236,222,0.05)')
        haze.addColorStop(1, 'rgba(226,236,222,0)')
        ctx.fillStyle = haze
        ctx.beginPath()
        ctx.ellipse(hx, hy, radius * 0.62, radius * 0.2, -0.25, 0, Math.PI * 2)
        ctx.fill()
      }
      ctx.restore()

      // City pulses
      const center: [number, number] = [-lambda, -phi]
      for (const city of CITIES) {
        const distance = geoDistance(city.coords, center)
        if (distance > Math.PI / 2 - 0.09) continue
        const point = projection(city.coords)
        if (!point) continue
        const fade = Math.min(1, (Math.PI / 2 - distance) * 4)
        const pulse = motionEnabled ? 0.5 + 0.5 * Math.sin(time * 0.002 + city.coords[0]) : 1
        ctx.globalAlpha = fade
        ctx.beginPath()
        ctx.arc(point[0], point[1], city.accent ? 2.2 : 1.5, 0, Math.PI * 2)
        ctx.fillStyle = city.accent ? '#e5c590' : '#c7d8c6'
        ctx.fill()
        if (city.accent) {
          ctx.beginPath()
          ctx.arc(point[0], point[1], 4 + pulse * 5, 0, Math.PI * 2)
          ctx.strokeStyle = `rgba(229,197,144,${0.34 * (1 - pulse)})`
          ctx.lineWidth = 1
          ctx.stroke()
        }
      }
      ctx.globalAlpha = 1

      // Edge vignette
      const vignette = ctx.createRadialGradient(cx, cy, radius * 0.7, cx, cy, radius * 1.18)
      vignette.addColorStop(0, 'rgba(0,0,0,0)')
      vignette.addColorStop(1, 'rgba(4,12,9,0.5)')
      ctx.fillStyle = vignette
      ctx.beginPath()
      ctx.arc(cx, cy, radius * 1.18, 0, Math.PI * 2)
      ctx.fill()

      // Rim light
      ctx.beginPath()
      ctx.arc(cx, cy, radius - 0.5, 0, Math.PI * 2)
      ctx.strokeStyle = 'rgba(205,220,200,0.22)'
      ctx.lineWidth = 1.1
      ctx.stroke()
    }

    resize()
    const observer = new ResizeObserver(resize)
    observer.observe(canvas)
    const visibilityObserver = new IntersectionObserver(
      (entries) => {
        visibleRef.current = entries[0]?.isIntersecting ?? true
      },
      { threshold: 0.02 },
    )
    visibilityObserver.observe(canvas)
    frameRef.current = requestAnimationFrame(draw)

    const onVisibility = () => {
      visibleRef.current = document.visibilityState === 'visible'
    }
    document.addEventListener('visibilitychange', onVisibility)

    return () => {
      cancelAnimationFrame(frameRef.current)
      observer.disconnect()
      visibilityObserver.disconnect()
      document.removeEventListener('visibilitychange', onVisibility)
    }
  }, [motionEnabled])

  const onPointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!interactive) return
    dragRef.current = { active: true, x: e.clientX, y: e.clientY, moved: 0 }
    e.currentTarget.setPointerCapture(e.pointerId)
  }
  const onPointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!dragRef.current.active) return
    const dx = e.clientX - dragRef.current.x
    const dy = e.clientY - dragRef.current.y
    dragRef.current.x = e.clientX
    dragRef.current.y = e.clientY
    dragRef.current.moved += Math.abs(dx) + Math.abs(dy)
    rotationRef.current[0] += dx * 0.28
    rotationRef.current[1] = Math.max(-62, Math.min(62, rotationRef.current[1] + dy * 0.2))
    idleRef.current = performance.now()
  }
  const endDrag = (e: React.PointerEvent<HTMLCanvasElement>) => {
    dragRef.current.active = false
    idleRef.current = performance.now()
    if (e.currentTarget.hasPointerCapture(e.pointerId)) {
      e.currentTarget.releasePointerCapture(e.pointerId)
    }
  }

  return (
    <canvas
      ref={canvasRef}
      className={`world-globe ${className}`}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={endDrag}
      onPointerCancel={endDrag}
      aria-label="كرة أرضية تفاعلية لخريطة العالم الحقيقية"
      role="img"
    />
  )
}

import { useEffect, useMemo, useRef, useState } from 'react'
import {
  geoGraticule10,
  geoNaturalEarth1,
  geoPath,
  type GeoProjection,
} from 'd3-geo'
import { feature } from 'topojson-client'
import countriesTopoRaw from 'world-atlas/countries-110m.json'
import type { Feature, FeatureCollection, Geometry } from 'geojson'
import type { Topology, GeometryCollection } from 'topojson-specification'
import { COUNTRY_BY_CCN3 } from '../data/countries'
import type { CountryRecord } from '../game/types'
import { formatPopulation } from '../lib/format'
import { LocateFixed, Minus, Plus, RotateCcw } from 'lucide-react'
import { IconButton } from './ui/Controls'

const topo = countriesTopoRaw as unknown as Topology<{ countries: GeometryCollection }>
const COUNTRIES = feature(topo, topo.objects.countries) as FeatureCollection<Geometry>
const graticule = geoGraticule10()

const WIDTH = 960
const HEIGHT = 500

function makeProjection(): GeoProjection {
  return geoNaturalEarth1().fitExtent(
    [
      [8, 6],
      [WIDTH - 8, HEIGHT - 6],
    ],
    { type: 'Sphere' },
  )
}

interface WorldMapProps {
  selectedCode?: string | null
  focusCode?: string | null
  onSelect?: (record: CountryRecord) => void
  picking?: boolean
  location?: [number, number] | null
  onLocationChange?: (coords: [number, number]) => void
  compact?: boolean
  markerLabel?: string
  className?: string
}

export function WorldMap({
  selectedCode,
  focusCode,
  onSelect,
  picking = false,
  location,
  onLocationChange,
  compact = false,
  markerLabel,
  className = '',
}: WorldMapProps) {
  const projection = useMemo(makeProjection, [])
  const path = useMemo(() => geoPath(projection), [projection])
  const wrapperRef = useRef<HTMLDivElement>(null)
  const svgRef = useRef<SVGSVGElement>(null)
  const [hover, setHover] = useState<{ record: CountryRecord | null; x: number; y: number } | null>(null)
  const [transform, setTransform] = useState('translate(0 0) scale(1)')
  const [zoom, setZoom] = useState(1)

  useEffect(() => {
    if (picking || !focusCode) {
      setTransform('translate(0 0) scale(1)')
      setZoom(1)
      return
    }
    const f = COUNTRIES.features.find((c) => COUNTRY_BY_CCN3.get(String(c.id))?.cca2 === focusCode)
    if (!f) return
    const bounds = path.bounds(f)
    const w = bounds[1][0] - bounds[0][0]
    const h = bounds[1][1] - bounds[0][1]
    if (w <= 0 || h <= 0) return
    const cx = (bounds[0][0] + bounds[1][0]) / 2
    const cy = (bounds[0][1] + bounds[1][1]) / 2
    const scale = Math.max(1.05, Math.min(7, Math.min((WIDTH * 0.55) / w, (HEIGHT * 0.6) / h)))
    setZoom(scale)
    setTransform(`translate(${WIDTH / 2 - cx * scale} ${HEIGHT / 2 - cy * scale}) scale(${scale})`)
  }, [focusCode, path, picking])

  const records = useMemo(() => {
    const map = new Map<string, CountryRecord | null>()
    for (const f of COUNTRIES.features) {
      map.set(String(f.id), COUNTRY_BY_CCN3.get(String(f.id)) ?? null)
    }
    return map
  }, [])

  const selectedFeatureCode = selectedCode
  const markerPoint = !picking && location ? projection(location) : picking && location ? projection(location) : null

  const handleMove = (e: React.MouseEvent<SVGPathElement>, record: CountryRecord | null) => {
    const rect = wrapperRef.current?.getBoundingClientRect()
    if (!rect) return
    setHover({ record, x: e.clientX - rect.left, y: e.clientY - rect.top })
  }

  const handleSvgClick = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!picking || !onLocationChange) return
    const svg = svgRef.current
    if (!svg) return
    const pt = svg.createSVGPoint()
    pt.x = e.clientX
    pt.y = e.clientY
    const ctm = svg.getScreenCTM()
    if (!ctm) return
    const local = pt.matrixTransform(ctm.inverse())
    const inverted = projection.invert?.([local.x, local.y])
    if (!inverted) return
    const [lng, lat] = inverted
    if (!Number.isFinite(lng) || !Number.isFinite(lat)) return
    if (Math.abs(lat) > 78) return
    onLocationChange([Math.round(lat * 10) / 10, Math.round(lng * 10) / 10])
  }

  const zoomBy = (factor: number) => {
    setZoom((prev) => {
      const next = Math.max(1, Math.min(7, prev * factor))
      if (next === 1) setTransform('translate(0 0) scale(1)')
      else {
        const cx = WIDTH / 2
        const cy = HEIGHT / 2
        setTransform(`translate(${cx - cx * next} ${cy - cy * next}) scale(${next})`)
      }
      return next
    })
  }

  return (
    <div
      ref={wrapperRef}
      className={`world-map ${compact ? 'world-map--compact' : ''} ${className}`}
    >
      <svg
        ref={svgRef}
        viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
        className={`world-map__svg ${picking ? 'is-picking' : ''}`}
        role="group"
        aria-label="خريطة العالم الحقيقية"
        onClick={handleSvgClick}
      >
        <defs>
          <radialGradient id="mapOcean" cx="42%" cy="36%" r="80%">
            <stop offset="0%" stopColor="#1c3d30" />
            <stop offset="65%" stopColor="#122b21" />
            <stop offset="100%" stopColor="#0a1c15" />
          </radialGradient>
          <filter id="mapGlow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="2.2" />
          </filter>
        </defs>
        <rect width={WIDTH} height={HEIGHT} fill="url(#mapOcean)" rx="18" />
        <g transform={transform} className="world-map__layer">
          <path d={path({ type: 'Sphere' }) ?? ''} fill="none" stroke="rgba(196,214,194,0.16)" strokeWidth="1" />
          <path d={path(graticule) ?? ''} fill="none" stroke="rgba(190,209,190,0.08)" strokeWidth="0.6" />
          {COUNTRIES.features.map((f) => {
            const key = String(f.id)
            const record = records.get(key)
            const isSelected = !!record && record.cca2 === selectedFeatureCode
            const isHovered = !!record && hover?.record?.cca2 === record.cca2
            return (
              <path
                key={key}
                d={path(f) ?? ''}
                className={`world-map__country ${isSelected ? 'is-selected' : ''} ${isHovered ? 'is-hovered' : ''} ${record ? '' : 'is-territory'}`}
                vectorEffect="non-scaling-stroke"
                onMouseEnter={(e) => handleMove(e, record)}
                onMouseMove={(e) => handleMove(e, record)}
                onMouseLeave={() => setHover(null)}
                onClick={(e) => {
                  if (picking) return
                  e.stopPropagation()
                  if (record && onSelect) onSelect(record)
                }}
                tabIndex={record && !picking ? 0 : -1}
                role={record && !picking ? 'button' : undefined}
                aria-label={record ? `اختيار ${record.nameAr}` : undefined}
                onKeyDown={(e) => {
                  if (!record || !onSelect || picking) return
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault()
                    onSelect(record)
                  }
                }}
              >
                <title>{record?.nameAr ?? ''}</title>
              </path>
            )
          })}
          {selectedFeatureCode &&
            COUNTRIES.features.map((f) => {
              const record = records.get(String(f.id))
              if (!record || record.cca2 !== selectedFeatureCode) return null
              return (
                <path
                  key={`outline-${f.id}`}
                  d={path(f) ?? ''}
                  fill="none"
                  stroke="#f0d6a4"
                  strokeWidth="1.8"
                  vectorEffect="non-scaling-stroke"
                  filter="url(#mapGlow)"
                  opacity="0.65"
                />
              )
            })}
          {markerPoint && (
            <g transform={`translate(${markerPoint[0]} ${markerPoint[1]})`} className="world-map__marker">
              <circle r="15" fill="rgba(220,185,124,0.12)" />
              <circle r="7" fill="rgba(220,185,124,0.22)" />
              <circle r="3.2" fill="#e9cf9e" stroke="#10241b" strokeWidth="1" />
              <line x1="0" y1="-11" x2="0" y2="-22" stroke="rgba(233,207,158,0.65)" strokeWidth="1" />
              {markerLabel && (
                <text
                  y="-27"
                  textAnchor="middle"
                  className="world-map__marker-label"
                  fill="#f2e6cf"
                  fontSize="10"
                >
                  {markerLabel}
                </text>
              )}
            </g>
          )}
        </g>
        {!picking && (
          <g className="world-map__controls">
            <g transform={`translate(${WIDTH - 40} 18)`}>
              <g onClick={(e) => { e.stopPropagation(); zoomBy(1.6) }}>
                <rect width="24" height="24" rx="7" fill="rgba(8,24,18,0.7)" stroke="rgba(232,219,196,0.16)" />
                <path d="M12 7v10M7 12h10" stroke="#e7d8bb" strokeWidth="1.4" strokeLinecap="round" />
              </g>
            </g>
            <g transform={`translate(${WIDTH - 40} 48)`}>
              <g onClick={(e) => { e.stopPropagation(); zoomBy(1 / 1.6) }}>
                <rect width="24" height="24" rx="7" fill="rgba(8,24,18,0.7)" stroke="rgba(232,219,196,0.16)" />
                <path d="M7 12h10" stroke="#e7d8bb" strokeWidth="1.4" strokeLinecap="round" />
              </g>
            </g>
          </g>
        )}
      </svg>

      {picking && (
        <div className="world-map__hint">
          <LocateFixed size={15} />
          <span>انقر على الموقع التقريبي لدولتك على الخريطة</span>
        </div>
      )}
      {!picking && !compact && (
        <div className="world-map__legend">
          <span className="world-map__dot" /> دولة قابلة للاختيار
          {selectedCode && (
            <span className="world-map__selected-label">
              <span className="world-map__dot world-map__dot--gold" /> المحددة
            </span>
          )}
        </div>
      )}
      {!picking && zoom > 1.05 && (
        <button
          type="button"
          className="world-map__reset"
          onClick={() => {
            setZoom(1)
            setTransform('translate(0 0) scale(1)')
          }}
        >
          <RotateCcw size={13} /> إعادة ضبط العرض
        </button>
      )}
      {hover && hover.record && !picking && (
        <div
          className="world-map__tooltip glass"
          style={{ left: hover.x, top: hover.y }}
        >
          <span className="world-map__tooltip-flag flag">
            <img src={`/flags/${hover.record.cca2.toLowerCase()}.svg`} alt="" />
          </span>
          <span>
            <strong>{hover.record.nameAr}</strong>
            <small>
              {hover.record.regionAr} · {formatPopulation(hover.record.population ?? 0)}
            </small>
          </span>
        </div>
      )}
      {!picking && !compact && (
        <div className="world-map__zoomread" aria-hidden>
          <IconButton label="تصغير الخريطة" onClick={() => zoomBy(1 / 1.6)}>
            <Minus size={13} />
          </IconButton>
          <span>{zoom.toFixed(1)}×</span>
          <IconButton label="تكبير الخريطة" onClick={() => zoomBy(1.6)}>
            <Plus size={13} />
          </IconButton>
        </div>
      )}
    </div>
  )
}

