  --bg-1: #0a1913;
  --bg-2: #10261d;
  --bg-3: #163327;
  --surface: rgba(15, 36, 27, 0.72);
  --surface-strong: rgba(18, 43, 33, 0.92);
  --surface-soft: rgba(240, 231, 213, 0.055);
  --surface-softer: rgba(240, 231, 213, 0.032);
  --ivory: #f2e8d7;
  --ivory-dim: #d9cdb9;
  --muted: #aab5aa;
  --faint: #7f9185;
  --bronze: #c7a269;
  --bronze-light: #e6cc9a;
  --bronze-dark: #886840;
  --sage: #a3bba7;
  --sage-dark: #5c8069;
  --clay: #c08468;
  --line: rgba(238, 229, 211, 0.12);
  --line-strong: rgba(238, 229, 211, 0.22);
  --forest-accent: #2d6b52;
  --radius-xl: 30px;
  --radius-lg: 22px;
  --radius-md: 16px;
  --radius-sm: 12px;
  --shadow-lg: 0 40px 90px -40px rgba(0, 0, 0, 0.85), 0 12px 32px -18px rgba(0, 0, 0, 0.55);
  --shadow-md: 0 18px 45px -25px rgba(0, 0, 0, 0.8);
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-soft: cubic-bezier(0.4, 0, 0.2, 1);
  --glass-blur: 28px;
  color-scheme: dark;
}

html {
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
  background: var(--bg-0);
}

html[data-text-scale='large'] {
  font-size: 17.2px;
}

html[data-text-scale='xlarge'] {
  font-size: 18.6px;
}

* {
  box-sizing: border-box;
}

