*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100dvh;
  font-family: 'IBM Plex Sans Arabic', 'Alexandria', system-ui, sans-serif;
  font-size: 0.95rem;
  line-height: 1.7;
  color: var(--ivory);
  background:
    radial-gradient(1100px 760px at 82% -8%, rgba(56, 102, 79, 0.2), transparent 62%),
    radial-gradient(900px 680px at 4% 108%, rgba(176, 138, 87, 0.1), transparent 60%),
    linear-gradient(160deg, #08130e 0%, #050c09 100%);
