  border-radius: 99px;
  border: 1px solid rgba(238, 229, 211, 0.13);
  background: rgba(238, 229, 211, 0.05);
  color: var(--ivory-dim);
  font-size: 0.72rem;
  line-height: 1.5;
  white-space: nowrap;
}

.chip--bronze {
  border-color: rgba(199, 162, 105, 0.28);
  background: rgba(199, 162, 105, 0.1);
  color: var(--bronze-light);
}

.chip--sage {
  border-color: rgba(163, 187, 167, 0.25);
  background: rgba(163, 187, 167, 0.08);
  color: var(--sage);
}

.chip--clay {
  border-color: rgba(192, 132, 104, 0.3);
  background: rgba(192, 132, 104, 0.1);
  color: #dfa88e;
}

.dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--sage);
  flex: none;
}

.dot--bronze {
  background: var(--bronze);
}

.dot--clay {
  background: var(--clay);
}

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(18px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes scaleIn {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes pulseDot {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(0.86);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

html[data-motion='reduced'] *,
html[data-motion='reduced'] *::before,
html[data-motion='reduced'] *::after {
  animation-duration: 0.001ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.001ms !important;
  scroll-behavior: auto !important;
}

@media (max-width: 600px) {
  body {
    font-size: 0.92rem;
  }
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  min-height: 46px;
  padding: 0 1.15rem;
  border-radius: 13px;
  border: 1px solid transparent;
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-size: 0.9rem;
  font-weight: 500;
  line-height: 1.2;
  color: var(--ivory);
  transition:
    transform 0.25s var(--ease),
    background-color 0.25s var(--ease-soft),
    border-color 0.25s var(--ease-soft),
    box-shadow 0.25s var(--ease-soft),
    opacity 0.2s;
  -webkit-tap-highlight-color: transparent;
}

.btn:hover:not(:disabled) {
  transform: translateY(-1px);
}

.btn:active:not(:disabled) {
  transform: translateY(0) scale(0.99);
}

.btn--full {
  width: 100%;
}

.btn--primary {
  background:
    linear-gradient(180deg, rgba(255, 249, 238, 0.98) 0%, rgba(237, 224, 202, 0.98) 100%);
  color: #10251b;
  border-color: rgba(255, 255, 255, 0.5);
  box-shadow:
    0 14px 32px -16px rgba(214, 180, 122, 0.6),
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    inset 0 -1px 0 rgba(144, 113, 70, 0.18);
  font-weight: 600;
}

.btn--primary:hover:not(:disabled) {
  box-shadow:
    0 20px 40px -18px rgba(214, 180, 122, 0.75),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
  background: linear-gradient(180deg, #fffaf0 0%, #f0e1c7 100%);
}

.btn--glass {
  background: rgba(240, 231, 213, 0.06);
  border-color: var(--line);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(14px);
}

.btn--glass:hover:not(:disabled) {
  background: rgba(240, 231, 213, 0.1);
  border-color: var(--line-strong);
}

.btn--outline {
  background: transparent;
  border-color: rgba(238, 229, 211, 0.2);
  color: var(--ivory-dim);
}

.btn--outline:hover:not(:disabled) {
  border-color: rgba(199, 162, 105, 0.5);
  color: var(--ivory);
  background: rgba(199, 162, 105, 0.06);
}

.btn--ghost {
  background: transparent;
  color: var(--muted);
}

.btn--ghost:hover:not(:disabled) {
  background: rgba(240, 231, 213, 0.06);
  color: var(--ivory);
}

.btn--danger {
  background: rgba(192, 132, 104, 0.12);
  border-color: rgba(192, 132, 104, 0.3);
  color: #e4ab90;
}

.btn--danger:hover:not(:disabled) {
  background: rgba(192, 132, 104, 0.2);
}

.btn:disabled {
  opacity: 0.4;
  transform: none;
}

.btn--sm {
  min-height: 36px;
  padding: 0 0.8rem;
  font-size: 0.78rem;
  border-radius: 10px;
}

.btn--lg {
  min-height: 54px;
  padding: 0 1.5rem;
  font-size: 0.98rem;
  border-radius: 15px;
}

.btn__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  min-width: 40px;
  border-radius: 12px;
  border: 1px solid transparent;
  color: var(--ivory-dim);
  background: transparent;
  transition: all 0.2s var(--ease-soft);
  -webkit-tap-highlight-color: transparent;
}

.icon-btn:hover {
  background: rgba(240, 231, 213, 0.08);
  border-color: var(--line);
  color: var(--ivory);
}

.icon-btn.is-active {
  background: rgba(199, 162, 105, 0.14);
  border-color: rgba(199, 162, 105, 0.28);
  color: var(--bronze-light);
}

.segmented {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 4px;
  border-radius: 14px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background: rgba(5, 14, 10, 0.45);
  box-shadow: inset 0 1px 4px rgba(0, 0, 0, 0.3);
  max-width: 100%;
}

.segmented__item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  min-height: 36px;
  padding: 0 0.9rem;
  border-radius: 10px;
  color: var(--muted);
  font-size: 0.8rem;
  white-space: nowrap;
  transition: all 0.22s var(--ease-soft);
}

.segmented__item:hover {
  color: var(--ivory);
}

.segmented__item.is-active {
  background: linear-gradient(180deg, rgba(240, 231, 213, 0.14), rgba(240, 231, 213, 0.07));
  color: var(--ivory);
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.13);
}

.segmented--compact .segmented__item {
  min-height: 30px;
  padding: 0 0.65rem;
  font-size: 0.72rem;
}

.toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.85rem 0;
  cursor: pointer;
}

.toggle-row__text {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.toggle-row__label {
  font-size: 0.9rem;
  color: var(--ivory);
}

.toggle-row__desc {
  font-size: 0.75rem;
  color: var(--faint);
  line-height: 1.5;
}

.toggle-row input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
}

.toggle {
  position: relative;
  width: 47px;
  height: 28px;
  border-radius: 99px;
  background: rgba(5, 14, 10, 0.7);
  border: 1px solid rgba(238, 229, 211, 0.16);
  flex: none;
  transition: all 0.25s var(--ease-soft);
}

.toggle__thumb {
  position: absolute;
  top: 3px;
  inset-inline-start: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #9aa89c;
  transition: transform 0.28s var(--ease), background-color 0.25s;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.4);
}

.toggle-row input:checked + .toggle {
  background: rgba(199, 162, 105, 0.28);
  border-color: rgba(199, 162, 105, 0.45);
}

.toggle-row input:checked + .toggle .toggle__thumb {
  transform: translateX(-19px);
  background: var(--bronze-light);
}

.toggle-row input:focus-visible + .toggle {
  outline: 2px solid rgba(230, 204, 154, 0.85);
  outline-offset: 3px;
}

.toggle-row.is-disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  min-width: 0;
}

.field__label {
  font-size: 0.78rem;
  color: var(--muted);
  font-weight: 500;
}

.field__input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.field__input {
  width: 100%;
  min-height: 48px;
  padding: 0 0.95rem;
  border-radius: 12px;
  border: 1px solid rgba(238, 229, 211, 0.13);
  background: rgba(4, 13, 9, 0.5);
  color: var(--ivory);
  font-size: 0.9rem;
  transition: border-color 0.2s, box-shadow 0.2s, background 0.2s;
}

.field__input::placeholder {
  color: rgba(170, 181, 170, 0.45);
}

.field__input:hover {
  border-color: rgba(238, 229, 211, 0.22);
}

.field__input:focus {
  outline: none;
  border-color: rgba(199, 162, 105, 0.55);
  box-shadow: 0 0 0 3px rgba(199, 162, 105, 0.1);
  background: rgba(4, 13, 9, 0.65);
}

.field__input[type='number']::-webkit-outer-spin-button,
.field__input[type='number']::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.field__input[type='number'] {
  -moz-appearance: textfield;
  appearance: textfield;
}

.field__suffix {
  position: absolute;
  inset-inline-end: 0.9rem;
  color: var(--faint);
  font-size: 0.75rem;
  pointer-events: none;
}

.field__hint {
  font-size: 0.71rem;
  color: var(--faint);
  line-height: 1.5;
}

.field__error {
  font-size: 0.72rem;
  color: #e0a48d;
}

.field--error .field__input {
  border-color: rgba(192, 132, 104, 0.5);
}

.range-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  padding: 0.7rem 0.85rem 0.6rem;
  border-radius: 14px;
  border: 1px solid rgba(238, 229, 211, 0.08);
  background: rgba(5, 14, 10, 0.28);
}

.range-field__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.range-field__label {
  font-size: 0.78rem;
  color: var(--muted);
}

.range-field__value {
  font-size: 0.78rem;
  color: var(--bronze-light);
  background: rgba(199, 162, 105, 0.09);
  border: 1px solid rgba(199, 162, 105, 0.18);
  padding: 0.1rem 0.55rem;
  border-radius: 7px;
  font-variant-numeric: tabular-nums;
}

.range-field input[type='range'] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 22px;
  background: transparent;
  margin: 0.2rem 0 0;
  cursor: pointer;
}

.range-field input[type='range']::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 99px;
  background: linear-gradient(
    to right,
    var(--bronze) 0%,
    var(--bronze) var(--fill, 50%),
    rgba(238, 229, 211, 0.13) var(--fill, 50%),
    rgba(238, 229, 211, 0.13) 100%
  );
}

.range-field input[type='range']::-moz-range-track {
  height: 4px;
  border-radius: 99px;
  background: rgba(238, 229, 211, 0.13);
}

.range-field input[type='range']::-moz-range-progress {
  height: 4px;
  border-radius: 99px;
  background: var(--bronze);
}

.range-field input[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  margin-top: -7px;
  border-radius: 50%;
  background: linear-gradient(180deg, #f8efdc, #ddc69e);
  border: 2px solid #173025;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(199, 162, 105, 0.6);
}

.range-field input[type='range']::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #f2e6cf;
  border: 2px solid #173025;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
}

.range-field__meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  font-size: 0.68rem;
  color: var(--faint);
  min-height: 1rem;
}

.range-field__reset {
  color: var(--bronze);
  font-size: 0.68rem;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.meter {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.meter__top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.meter__label {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.78rem;
  color: var(--muted);
}

.meter__value {
  font-size: 0.82rem;
  color: var(--ivory);
  font-variant-numeric: tabular-nums;
  font-weight: 500;
}

.meter__track {
  height: 6px;
  border-radius: 99px;
  background: rgba(238, 229, 211, 0.09);
  overflow: hidden;
}

.meter__fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(163, 187, 167, 0.6), var(--sage));
  transition: width 0.6s var(--ease);
}

.meter--bronze .meter__fill {
  background: linear-gradient(90deg, rgba(199, 162, 105, 0.55), var(--bronze-light));
}

.meter--stone .meter__fill {
  background: linear-gradient(90deg, rgba(160, 170, 160, 0.4), #aeb7ad);
}

.meter--clay .meter__fill {
  background: linear-gradient(90deg, rgba(192, 132, 104, 0.45), #d49b81);
}

.meter__hint {
  font-size: 0.68rem;
  color: var(--faint);
}

.meter--small .meter__label {
