}

.flag--sm {
  width: 30px;
  border-radius: 5px;
}

.flag--md {
  width: 52px;
  border-radius: 8px;
}

.flag--lg {
  width: 82px;
  border-radius: 11px;
}

.flag--xl {
  width: 100%;
  border-radius: 14px;
}

.emblem {
  width: 82px;
  height: 82px;
  filter: drop-shadow(0 8px 18px rgba(0, 0, 0, 0.4));
  flex: none;
}

.emblem--sm {
  width: 48px;
  height: 48px;
}

.emblem--lg {
  width: 116px;
  height: 116px;
}

.emblem--xl {
  width: 148px;
  height: 148px;
}

.world-globe {
  width: 100%;
  height: 100%;
  touch-action: pan-y;
  cursor: grab;
}

.world-globe:active {
  cursor: grabbing;
}

.world-map {
  position: relative;
  border-radius: 18px;
  overflow: hidden;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background: #0a1b14;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
  isolation: isolate;
}

.world-map__svg {
  width: 100%;
  height: auto;
  display: block;
