  font-size: 0.65rem;
  color: var(--muted);
  line-height: 1.4;
}

.world-map__tooltip-flag {
  width: 30px;
}

.world-map__legend {
  position: absolute;
  bottom: 10px;
  inset-inline-start: 12px;
  display: flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.25rem 0.55rem;
  border-radius: 8px;
  background: rgba(5, 16, 11, 0.65);
  border: 1px solid rgba(238, 229, 211, 0.08);
  font-size: 0.63rem;
  color: var(--muted);
  backdrop-filter: blur(8px);
