  height: 6px;
  border-radius: 2px;
  background: #4d7259;
}

.world-map__dot--gold {
  background: var(--bronze);
}

.world-map__selected-label {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-inline-start: 0.4rem;
