  top: 10px;
  inset-inline-start: 12px;
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.3rem 0.6rem;
  border-radius: 8px;
  background: rgba(5, 16, 11, 0.72);
