  display: flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.3rem 0.65rem;
  border-radius: 99px;
  background: rgba(5, 16, 11, 0.76);
  border: 1px solid rgba(199, 162, 105, 0.25);
  color: var(--bronze-light);
  font-size: 0.65rem;
  backdrop-filter: blur(8px);
  white-space: nowrap;
