.world-map__zoomread {
  position: absolute;
  bottom: 10px;
  inset-inline-end: 12px;
  display: flex;
  align-items: center;
  gap: 0.15rem;
  padding: 0.15rem;
  border-radius: 10px;
  background: rgba(5, 16, 11, 0.72);
  border: 1px solid rgba(238, 229, 211, 0.09);
  backdrop-filter: blur(8px);
