.world-map__zoomread .icon-btn {
  width: 26px;
  height: 26px;
  min-width: 26px;
  border-radius: 7px;
}

.world-map__zoomread span {
  font-size: 0.63rem;
  color: var(--muted);
  min-width: 26px;
  text-align: center;
  font-variant-numeric: tabular-nums;
