.modal-layer {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(3, 9, 6, 0.62);
  backdrop-filter: blur(10px);
  animation: fadeIn 0.25s ease;
