.modal {
  position: relative;
  width: min(560px, 100%);
  max-height: min(88dvh, 860px);
  display: flex;
  flex-direction: column;
  border-radius: 26px;
  animation: scaleIn 0.4s var(--ease) both;
  background: linear-gradient(160deg, rgba(26, 54, 42, 0.96), rgba(8, 22, 16, 0.98));
  box-shadow: 0 50px 110px -40px rgba(0, 0, 0, 0.9);
