}

.modal--lg {
  width: min(760px, 100%);
}

.modal__handle {
  display: none;
}

.modal__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.35rem 1.5rem 0.75rem;
}

.modal__title {
  font-size: 1.25rem;
}

.modal__subtitle {
  margin-top: 0.25rem;
  font-size: 0.78rem;
  color: var(--muted);
  line-height: 1.6;
}

.modal__body {
  padding: 0.5rem 1.5rem 1.1rem;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.modal__footer {
  display: flex;
  gap: 0.6rem;
  padding: 0.9rem 1.5rem 1.35rem;
  border-top: 1px solid rgba(238, 229, 211, 0.08);
}

.modal__footer .btn {
  flex: 1;
}

.toast-stack {
  position: fixed;
  z-index: 300;
  bottom: calc(1.5rem + env(safe-area-inset-bottom, 0px));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: min(420px, calc(100vw - 2rem));
  pointer-events: none;
}

.toast {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.65rem 0.8rem;
  border-radius: 13px;
  background: rgba(16, 38, 29, 0.94);
  border: 1px solid rgba(238, 229, 211, 0.14);
  box-shadow: 0 20px 45px -20px rgba(0, 0, 0, 0.9);
  backdrop-filter: blur(18px);
  font-size: 0.8rem;
  color: var(--ivory);
  animation: fadeUp 0.35s var(--ease) both;
  pointer-events: auto;
}

.toast svg {
  flex: none;
  color: var(--sage);
}

.toast--success svg {
  color: #a9c8a4;
}

.toast--error svg {
  color: #e0a48d;
}

.toast__close {
  color: var(--faint);
  padding: 0.2rem;
  margin-inline-start: auto;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.8rem;
}

.logo-mark {
  filter: drop-shadow(0 8px 20px rgba(0, 0, 0, 0.4));
}

.brand__text {
  display: flex;
  flex-direction: column;
  gap: 0.05rem;
}

.brand__name {
  font-family: 'Alexandria', sans-serif;
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--ivory);
  line-height: 1.2;
}

.brand__sub {
  font-size: 0.55rem;
  letter-spacing: 0.16em;
  color: var(--bronze);
  line-height: 1.4;
}

.brand--compact .brand__name {
  font-size: 1.1rem;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.8rem;
}

.inset-panel {
  padding: 1rem;
  border-radius: var(--radius-md);
  border: 1px solid rgba(238, 229, 211, 0.08);
  background: rgba(4, 13, 9, 0.28);
}

.info-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.5rem 0;
  border-bottom: 1px solid rgba(238, 229, 211, 0.07);
  font-size: 0.8rem;
}

.info-row:last-child {
  border-bottom: 0;
}

.info-row__label {
  color: var(--muted);
}

.info-row__value {
  color: var(--ivory);
  text-align: end;
  font-weight: 500;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 3rem 1.5rem;
  gap: 0.8rem;
  border-radius: var(--radius-lg);
  border: 1px dashed rgba(238, 229, 211, 0.14);
  background: rgba(238, 229, 211, 0.018);
}

.empty-state__icon {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(199, 162, 105, 0.09);
  border: 1px solid rgba(199, 162, 105, 0.2);
  color: var(--bronze-light);
}

.empty-state h3 {
  font-size: 1.05rem;
}

.empty-state p {
  max-width: 44ch;
  font-size: 0.8rem;
  color: var(--muted);
  line-height: 1.75;
}

@media (max-width: 600px) {
  .modal-layer {
    padding: 0;
    align-items: flex-end;
  }

  .modal--sheet {
    width: 100%;
    max-height: 92dvh;
    border-radius: 24px 24px 0 0;
    animation: fadeUp 0.35s var(--ease) both;
  }

  .modal__handle {
    display: block;
    width: 42px;
    height: 4px;
    border-radius: 99px;
    background: rgba(238, 229, 211, 0.25);
    margin: 0.6rem auto 0;
  }

  .modal__header {
    padding: 0.85rem 1.15rem 0.6rem;
  }

  .modal__body {
    padding: 0.4rem 1.15rem 1rem;
  }

  .modal__footer {
    padding: 0.8rem 1.15rem calc(1.1rem + env(safe-area-inset-bottom, 0px));
  }

  .modal__footer {
    flex-wrap: wrap;
  }

  .card-grid {
    grid-template-columns: 1fr;
  }

  .flag {
    width: 38px;
  }

  .flag--lg {
    width: 68px;
  }

  .emblem {
    width: 68px;
    height: 68px;
  }

  .emblem--lg {
    width: 94px;
    height: 94px;
  }

  .emblem--xl {
    width: 116px;
    height: 116px;
  }

  .world-map__tooltip {
    display: none;
  }

  .world-map__legend {
    font-size: 0.6rem;
  }

  .toast-stack {
    bottom: calc(5.6rem + env(safe-area-inset-bottom, 0px));
  }
}

/* ---------- Shared sub-screen shell ---------- */
.screen {
  position: relative;
  min-height: 100dvh;
  overflow: hidden;
}

.screen__ambient {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(900px 640px at 88% -8%, rgba(61, 108, 82, 0.22), transparent 62%),
    radial-gradient(760px 560px at 4% 102%, rgba(176, 138, 87, 0.12), transparent 60%),
    linear-gradient(160deg, #08140f 0%, #050c09 100%);
}

.screen__ambient::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(238, 229, 211, 0.017) 1px, transparent 1px),
    linear-gradient(90deg, rgba(238, 229, 211, 0.017) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(circle at 60% 20%, rgba(0, 0, 0, 0.7), transparent 70%);
}

.screen__inner {
  position: relative;
  z-index: 2;
  max-width: 1220px;
  margin: 0 auto;
  padding: 0 clamp(1rem, 4vw, 3rem) 4rem;
}

.screen-topbar {
  position: relative;
  z-index: 6;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.1rem clamp(1rem, 4vw, 3rem) 0.6rem;
  max-width: 1320px;
  margin: 0 auto;
}

.screen-topbar__actions {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}

.screen-title-block {
  padding: 1.5rem 0 1.6rem;
  max-width: 720px;
}

.screen-title-block h1 {
  font-size: clamp(2rem, 4.2vw, 3.1rem);
  margin: 0.55rem 0 0.6rem;
  letter-spacing: -0.01em;
}

.screen-title-block p {
  color: var(--muted);
  font-size: 0.9rem;
  line-height: 1.8;
  max-width: 58ch;
}

/* ---------- Main menu ---------- */
.menu-screen {
  position: relative;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background:
    radial-gradient(1000px 800px at 18% 44%, rgba(48, 95, 72, 0.26), transparent 64%),
    radial-gradient(800px 620px at 92% -8%, rgba(176, 138, 87, 0.12), transparent 58%),
    linear-gradient(155deg, #09150f 0%, #050c09 60%, #040a07 100%);
}

.menu-scene {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.menu-globe {
  position: absolute;
  top: 50%;
  left: -9vw;
  width: min(70vw, 880px);
  height: min(70vw, 880px);
  transform: translateY(-50%);
  opacity: 0.96;
  animation: menuGlobeIn 1.6s var(--ease) both;
}

.menu-globe::before {
  content: '';
  position: absolute;
  inset: 12%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(90, 150, 111, 0.24), transparent 66%);
  filter: blur(50px);
}

@keyframes menuGlobeIn {
  from {
    opacity: 0;
    transform: translateY(-50%) scale(0.92);
  }
  to {
    opacity: 0.96;
    transform: translateY(-50%) scale(1);
  }
}

.menu-aurora {
  position: absolute;
  border-radius: 50%;
  filter: blur(90px);
  pointer-events: none;
}

.menu-aurora--one {
  width: 42vw;
  height: 28vw;
  background: rgba(122, 164, 129, 0.09);
  top: -8%;
  right: 16%;
  animation: auroraDrift 24s ease-in-out infinite alternate;
}

.menu-aurora--two {
  width: 30vw;
  height: 26vw;
  background: rgba(199, 162, 105, 0.07);
  bottom: -10%;
  left: 18%;
  animation: auroraDrift 30s ease-in-out infinite alternate-reverse;
}

@keyframes auroraDrift {
  from {
    transform: translate3d(0, 0, 0) scale(1);
  }
  to {
    transform: translate3d(-4vw, 3vh, 0) scale(1.12);
  }
}

.menu-scrim {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to left, rgba(4, 11, 8, 0.35) 0%, rgba(4, 11, 8, 0.72) 46%, rgba(4, 11, 8, 0.28) 78%, rgba(4, 11, 8, 0.55) 100%),
    linear-gradient(to top, rgba(4, 10, 7, 0.94) 0%, transparent 36%),
    radial-gradient(80% 100% at 50% 50%, transparent 40%, rgba(3, 8, 6, 0.55) 100%);
}

.menu-topbar {
  position: relative;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.25rem clamp(1rem, 4vw, 3.2rem);
  animation: fadeIn 1s ease 0.2s both;
}

.menu-stage {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.38rem 0.8rem;
  border-radius: 99px;
  border: 1px solid rgba(238, 229, 211, 0.12);
  background: rgba(7, 19, 13, 0.4);
  backdrop-filter: blur(12px);
  font-size: 0.67rem;
  color: var(--muted);
  letter-spacing: 0.03em;
}

.menu-stage .dot {
  animation: pulseDot 3s ease-in-out infinite;
}

.menu-main {
  position: relative;
  z-index: 4;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  width: 100%;
  max-width: 1420px;
  margin: 0 auto;
  padding: 0.5rem clamp(1rem, 4vw, 3.2rem) 3rem;
}

.menu-content {
  width: min(470px, 100%);
  margin-inline-start: auto;
  display: flex;
  flex-direction: column;
  gap: 1.35rem;
  animation: fadeUp 0.9s var(--ease) 0.1s both;
}

.menu-heading {
  position: relative;
}

.menu-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  color: var(--bronze-light);
}

.menu-kicker::before {
  content: '';
  width: 26px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--bronze));
}

.menu-title {
  margin: 0.4rem 0 0;
  font-family: 'Alexandria', sans-serif;
  font-size: clamp(3.3rem, 7vw, 5rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.015em;
  background: linear-gradient(175deg, #fbf5e8 8%, #efe2ca 46%, #cbb07c 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 12px 30px rgba(0, 0, 0, 0.38));
}

.menu-tagline {
  margin: 0.4rem 0 0.5rem;
  font-family: 'Alexandria', sans-serif;
  font-size: clamp(1rem, 1.7vw, 1.22rem);
  font-weight: 300;
  color: var(--ivory-dim);
  line-height: 1.6;
}

.menu-desc {
  max-width: 44ch;
  font-size: 0.82rem;
  line-height: 1.85;
  color: var(--muted);
}

.menu-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.95rem;
}

.menu-panel {
  padding: 0.55rem;
  border-radius: 26px;
}

.menu-panel::before {
  background:
    radial-gradient(120% 90% at 88% -20%, rgba(255, 248, 232, 0.09), transparent 52%),
    linear-gradient(100deg, transparent 32%, rgba(255, 255, 255, 0.025) 50%, transparent 66%);
}

.menu-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.menu-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  width: 100%;
  padding: 0.68rem 0.75rem;
  border-radius: 17px;
  text-align: start;
  color: var(--ivory);
  border: 1px solid transparent;
  transition:
    background 0.22s var(--ease-soft),
    border-color 0.22s,
    transform 0.25s var(--ease),
    box-shadow 0.25s;
  -webkit-tap-highlight-color: transparent;
}

.menu-row:hover:not(:disabled) {
  background: rgba(240, 231, 213, 0.065);
  border-color: rgba(238, 229, 211, 0.1);
  transform: translateX(-2px);
}

.menu-row:active:not(:disabled) {
  transform: translateX(0) scale(0.995);
}

.menu-row__icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  flex: none;
  border-radius: 12px;
  background: rgba(240, 231, 213, 0.05);
  border: 1px solid rgba(238, 229, 211, 0.1);
  color: var(--sage);
  transition: all 0.25s;
}

.menu-row:hover:not(:disabled) .menu-row__icon {
  border-color: rgba(199, 162, 105, 0.28);
  color: var(--bronze-light);
}

.menu-row__text {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.05rem;
}

.menu-row__text strong {
  font-size: 0.94rem;
  font-weight: 500;
  line-height: 1.4;
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.menu-row__text small {
  font-size: 0.68rem;
  color: var(--faint);
  line-height: 1.45;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.menu-row__chevron {
  color: var(--faint);
  flex: none;
  transition: transform 0.25s var(--ease), color 0.2s;
}

.menu-row:hover:not(:disabled) .menu-row__chevron {
  color: var(--bronze-light);
  transform: translateX(-3px);
}

.menu-row--primary {
  background: linear-gradient(180deg, #faf3e6 0%, #eaddc6 100%);
  border-color: rgba(255, 255, 255, 0.55);
  box-shadow:
    0 18px 40px -20px rgba(199, 162, 105, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
  color: #10241a;
  padding: 0.8rem 0.8rem;
}

.menu-row--primary:hover:not(:disabled) {
  background: linear-gradient(180deg, #fffaf0, #f0e2c9);
  box-shadow: 0 24px 48px -22px rgba(199, 162, 105, 0.7);
  border-color: rgba(255, 255, 255, 0.7);
}

.menu-row--primary .menu-row__icon {
  background: rgba(24, 58, 44, 0.1);
  border-color: rgba(24, 58, 44, 0.16);
  color: #234b39;
}

.menu-row--primary .menu-row__text strong {
  font-weight: 600;
  font-size: 1rem;
}

.menu-row--primary .menu-row__text small {
  color: rgba(16, 36, 26, 0.6);
}

.menu-row--primary .menu-row__chevron {
  color: rgba(16, 36, 26, 0.55);
}

.menu-row--primary:hover .menu-row__chevron {
  color: #10241a;
}

.menu-row--continue .menu-row__text small {
  color: var(--bronze);
  opacity: 0.9;
}

.menu-row:disabled {
  opacity: 0.45;
}

.menu-row:disabled .menu-row__text small {
  color: var(--faint);
}

.menu-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.15rem 0.55rem 0;
  font-size: 0.65rem;
  color: var(--faint);
}

.menu-foot__links {
  display: flex;
  align-items: center;
  gap: 0.9rem;
}

.menu-foot button {
  color: var(--muted);
  font-size: 0.67rem;
  transition: color 0.2s;
}

.menu-foot button:hover {
  color: var(--bronze-light);
}

.menu-corner {
  position: absolute;
  z-index: 5;
  bottom: 1.1rem;
  left: 1.6rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.6rem;
  color: rgba(170, 181, 170, 0.55);
  letter-spacing: 0.08em;
}

.menu-corner span {
  width: 18px;
  height: 1px;
  background: rgba(199, 162, 105, 0.4);
}

/* ---------- Scenarios ---------- */
.scenario-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  margin-bottom: 1.5rem;
}

.scenario-filters button {
  padding: 0.4rem 0.9rem;
  border-radius: 99px;
  border: 1px solid rgba(238, 229, 211, 0.12);
  color: var(--muted);
  font-size: 0.77rem;
  background: rgba(240, 231, 213, 0.03);
  transition: all 0.2s;
}

.scenario-filters button:hover {
  color: var(--ivory);
  border-color: rgba(238, 229, 211, 0.25);
}

.scenario-filters button.is-active {
  background: rgba(199, 162, 105, 0.13);
  border-color: rgba(199, 162, 105, 0.35);
  color: var(--bronze-light);
}

.scenario-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.scenario-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  padding: 1.35rem;
  border-radius: 22px;
  overflow: hidden;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background:
    radial-gradient(120% 100% at 100% 0%, rgba(199, 162, 105, 0.06), transparent 46%),
    linear-gradient(155deg, rgba(38, 72, 56, 0.4), rgba(10, 26, 19, 0.72));
  backdrop-filter: blur(16px);
  transition:
    transform 0.3s var(--ease),
    border-color 0.3s,
    box-shadow 0.3s;
}

.scenario-card::before {
  content: '';
  position: absolute;
  top: 0;
  inset-inline: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--card-accent, var(--bronze)), transparent);
  opacity: 0.65;
}

.scenario-card:hover {
  transform: translateY(-3px);
  border-color: rgba(199, 162, 105, 0.26);
  box-shadow: 0 28px 60px -34px rgba(0, 0, 0, 0.9);
}

.scenario-card__year {
  position: absolute;
  top: 0.35rem;
  left: 0.9rem;
  font-family: 'Alexandria', sans-serif;
  font-size: 4.6rem;
  font-weight: 700;
  line-height: 1;
  color: rgba(238, 229, 211, 0.035);
  pointer-events: none;
  letter-spacing: -0.04em;
}

.scenario-card__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  position: relative;
}

.scenario-card h3 {
  font-size: 1.22rem;
  line-height: 1.35;
}

.scenario-card__subtitle {
  color: var(--card-accent, var(--bronze-light));
  font-size: 0.78rem;
  margin-top: -0.35rem;
}

.scenario-card__desc {
  font-size: 0.79rem;
  line-height: 1.75;
  color: var(--muted);
}

.scenario-card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.1rem;
}

.scenario-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-top: auto;
  padding-top: 0.8rem;
  border-top: 1px solid rgba(238, 229, 211, 0.08);
}

.scenario-card__country {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  font-size: 0.75rem;
  color: var(--ivory-dim);
}

/* ---------- Saves ---------- */
.saves-list {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.save-card {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  padding: 0.9rem 1rem;
  border-radius: 18px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background: linear-gradient(150deg, rgba(34, 66, 51, 0.36), rgba(9, 25, 18, 0.66));
  backdrop-filter: blur(16px);
  transition: all 0.25s var(--ease);
}

.save-card:hover {
  border-color: rgba(199, 162, 105, 0.24);
  transform: translateY(-1px);
}

.save-card__main {
  flex: 1;
  min-width: 0;
}

.save-card__name {
  font-size: 0.95rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.save-card__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.7rem;
  margin-top: 0.18rem;
  font-size: 0.68rem;
  color: var(--faint);
}

.save-card__meta span {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
}

.save-card__actions {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  flex: none;
}

.save-card__actions .icon-btn {
  width: 36px;
  height: 36px;
  min-width: 36px;
}

/* ---------- Settings ---------- */
.settings-layout {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  max-width: 760px;
}

.settings-group {
  padding: 1.15rem 1.25rem;
}

.settings-group h2 {
  font-size: 1rem;
  margin-bottom: 0.15rem;
}

.settings-group__hint {
  font-size: 0.74rem;
  color: var(--faint);
  line-height: 1.6;
  margin-bottom: 0.7rem;
}

.settings-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.85rem 0;
  border-top: 1px solid rgba(238, 229, 211, 0.07);
}

.settings-row__label {
  font-size: 0.84rem;
}

.settings-row__desc {
  font-size: 0.72rem;
  color: var(--faint);
  margin-top: 0.12rem;
  line-height: 1.5;
}

.data-source {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  padding: 0.55rem 0;
  border-top: 1px solid rgba(238, 229, 211, 0.07);
  font-size: 0.76rem;
}

.data-source strong {
  color: var(--ivory-dim);
  font-weight: 500;
  min-width: 88px;
}

.data-source span {
  color: var(--faint);
  line-height: 1.6;
}

.storage-warning {
  display: flex;
  gap: 0.55rem;
  align-items: flex-start;
  padding: 0.75rem 0.9rem;
  border-radius: 12px;
  background: rgba(192, 132, 104, 0.1);
  border: 1px solid rgba(192, 132, 104, 0.24);
  color: #e2b19a;
  font-size: 0.75rem;
  line-height: 1.6;
  margin-top: 0.7rem;
}

.danger-zone {
  border-color: rgba(192, 132, 104, 0.2);
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .menu-globe {
    left: -22vw;
    width: 82vw;
    height: 82vw;
    opacity: 0.72;
  }

  .menu-content {
    width: min(440px, 92%);
  }

  .scenario-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .menu-screen {
    min-height: 100dvh;
    overflow-y: auto;
  }

  .menu-scene {
    position: fixed;
  }

  .menu-globe {
    top: -6vw;
    left: 50%;
    transform: translateX(-50%);
    width: 142vw;
    height: 142vw;
    opacity: 0.62;
    animation: menuGlobeMobileIn 1.4s var(--ease) both;
  }

  @keyframes menuGlobeMobileIn {
    from {
      opacity: 0;
      transform: translateX(-50%) scale(0.92);
    }
    to {
      opacity: 0.62;
      transform: translateX(-50%) scale(1);
    }
  }

  .menu-scrim {
    position: fixed;
    background:
      linear-gradient(to top, #050c09 4%, rgba(4, 11, 8, 0.92) 42%, rgba(4, 11, 8, 0.35) 74%, rgba(4, 11, 8, 0.5) 100%),
      radial-gradient(90% 60% at 50% 30%, transparent 30%, rgba(3, 8, 6, 0.4) 100%);
  }

  .menu-topbar {
    padding: 0.9rem 1rem;
  }

  .menu-stage {
    font-size: 0.6rem;
    padding: 0.3rem 0.6rem;
  }

  .menu-main {
    align-items: flex-end;
    padding: 34vh 1rem calc(1.2rem + env(safe-area-inset-bottom, 0px));
  }

  .menu-content {
    width: 100%;
    margin: 0;
    gap: 1rem;
  }

  .menu-title {
    font-size: clamp(3.1rem, 16vw, 4.4rem);
  }

  .menu-tagline {
    font-size: 0.98rem;
  }

  .menu-desc {
    font-size: 0.78rem;
    line-height: 1.7;
    max-width: 100%;
  }

  .menu-facts {
    margin-top: 0.65rem;
  }

  .menu-row {
    padding: 0.6rem 0.65rem;
    gap: 0.65rem;
    border-radius: 15px;
  }

  .menu-row--primary {
    padding: 0.7rem 0.7rem;
  }

  .menu-row__icon {
    width: 37px;
    height: 37px;
    border-radius: 11px;
  }

  .menu-row__text strong {
    font-size: 0.9rem;
  }

  .menu-row__text small {
    font-size: 0.64rem;
  }

  .menu-corner {
    display: none;
  }

  .screen-topbar {
    padding: 0.9rem 1rem 0.4rem;
  }

  .screen__inner {
    padding: 0 1rem 6rem;
  }

  .screen-title-block {
    padding: 1rem 0 1.2rem;
  }

  .screen-title-block h1 {
    font-size: clamp(1.8rem, 8vw, 2.4rem);
  }

  .scenario-grid {
    grid-template-columns: 1fr;
  }

  .save-card {
    flex-wrap: wrap;
    align-items: flex-start;
  }

  .save-card__actions {
    width: 100%;
    justify-content: flex-end;
    border-top: 1px solid rgba(238, 229, 211, 0.08);
    padding-top: 0.55rem;
  }

  .save-card__actions .btn {
    flex: 1;
  }

  .settings-row {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
  }

  .settings-row .segmented {
    width: 100%;
  }

  .settings-row .segmented__item {
    flex: 1;
  }

  .settings-row .toggle-row {
    width: 100%;
    padding: 0;
  }
}

@media (max-width: 380px) {
  .menu-stage {
    display: none;
  }

  .menu-main {
    padding-top: 30vh;
  }

  .menu-row__text small {
    display: none;
  }
}

@media (max-height: 720px) and (min-width: 761px) {
  .menu-title {
    font-size: 3.6rem;
  }

  .menu-desc {
    display: none;
  }

  .menu-row {
    padding: 0.5rem 0.7rem;
  }

  .menu-row__icon {
    width: 36px;
    height: 36px;
  }
}

content.text:
Now wizard.css. Need classes for:
- wizard screen shell, topbar, stepper, content, footer.
- step containers, cards.
- world cards.
- country picker.
- identity form/preview.
- flag/emblem designers.
- government cards.
- conditions.

Let's design markup and CSS together.

Wizard topbar:
```
.wizard-screen .wizard-top {display flex; justify-between; ...}
.wizard-progress {display flex; gap; align center; padding ...; max-width 1120; margin auto}
.step-pill {display flex; align center; gap; color faint; flex 1; position}
.step-pill__num circle 28
.step-pill.is-active ...
.step-pill.is-done ...
connector line via ::after
```
Mobile: hide labels, show 5 circles with connector; plus "الخطوة x من 5 · title".

Wizard main: max 1120, padding 0 24 140 (footer space).
Step header `.step-head` margin.
`.step-title` 1.9rem.
`.step-lede` muted.

World cards:
```
.world-grid {display grid; grid-template-columns repeat(6,1fr); gap 12}
.world-card {grid-column span 2; padding 20; text-align start; border radius 20; ...}
.world-card:nth-child(1), nth-child(2) {grid-column span 3}
.world-card.is-active {...}
.world-card__icon...
```
Maybe 5 cards: first two 3-col, next three 2-col. Good.
Scenario selector cards horizontal maybe 3 cols. `.scenario-pick-grid` 2 cols. Reuse smaller `.scenario-mini`.

World settings panel `.world-config` grid 4 cols; collapsible? Show below if fictional/custom. For real, show a slim note + difficulty selector (needed for starting conditions). Difficulty always shown in a horizontal set of 4 cards. `.difficulty-grid`.

Step 2:
```
.country-kind-tabs margin
.country-picker {display grid; grid-template-columns 1.15fr 0.85fr; grid-template-areas "list map"; gap 14}
.country-list-panel {grid-area list; ... max-height 560; display flex column}
.country-map-wrap {grid-area map; display flex column; gap}
.search-row...
.region-chips {display flex; flex-wrap wrap; gap; max-height?}
.country-list {overflow-y auto; display flex column; gap 4; padding-inline-end 4}
.country-option {display flex; gap .6; padding .55 .6; border radius 12; text-align start; border}
.country-option.is-active {background rgba(bronze...)}
.country-option__name; small
.country-map-wrap .world-map {flex:1; aspect-ratio: 1.7/1}
.selected-country-card
```
Fictional selection:
`.fictional-choice` big panel with emblem/flag illustration, 3 features, name? We'll render in step 2 as a card with "اختر أرضاً جديدة" and stats, plus "الموقع والهوية في الخطوة التالية". Could include a map illustration with marker. Use a 2-col panel.
Maybe the country kind tabs plus content.

Step 3:
```
.identity-layout {display grid; grid-template-columns: 1fr 390px; gap 16; align start}
.identity-form {display flex column gap 14}
.form-section {padding 18; border radius 20; border; background rgba}
.form-section__head
.form-grid {display grid; grid-template-columns 1fr 1fr; gap 12}
.form-grid--3
.language-chips
.custom-add-row
.identity-options grid 2 cols small cards
.flag-designer
.flag-patterns {display grid; grid-template-columns repeat(4,1fr)}
.pattern-btn {aspect ratio 4/3; border; border radius; overflow hidden; opacity}
.palette-row {display flex; align center; gap}
.swatch {width 28; height 28; border-radius 50%; border 2px solid transparent}
.flag-symbols {display flex wrap gap}
.symbol-chip {padding 4 10; border...}
.emblem-designer grid 3 cols controls?
.preview-sticky {position sticky; top 16}
.identity-preview {padding 20; ...}
.identity-preview__flag ...
```
The preview panel should be gorgeous: large flag with sheen, emblem overlapping, name, official name, details. Maybe dark gradient with texture.

Territory section map. `.territory-map .world-map`.

Step 4:
```
.gov-grid {display grid; grid-template-columns repeat(3,1fr); gap 10}
.gov-card {padding 16; border radius 18; text-align start; ...; min-height 180}
.gov-card.is-active {border bronze; background}
.gov-card__icon 42
.gov-card__top flex
.gov-card__desc font .73 line clamp 2
.gov-card__traits chips small
.gov-difficulty dots
.gov-detail {display grid 2 cols; margin top; ...}
.gov-structure grid 2/4
.power-grid
.custom-gov {grid col span full; padding}
```
Step 4 long list; okay scroll.

Step 5:
```
.cond-mode-row flex justify-between
.quick-summary grid 3 cards
.overview-meters grid 2 cols
.cond-note
.advanced-grid {display grid; grid-template-columns 1fr 1fr; gap 8}
.advanced-group {padding 16; ...}
.advanced-group--full
.cond-population inputs grid
```
Footer:
```
.wizard-footer {position fixed bottom 0; left0 right0; z 40; padding .8 1rem calc(.8+safe); background linear-gradient(to top, bg 20%, transparent); pointer-events none}
.wizard-footer__inner {pointer-events auto; max-width 1120; margin auto; display flex; justify-between; gap; padding .65rem .75rem; border radius 18; glass}
.wizard-error {color clay; small}
.stepcount
```
On mobile footer buttons expand; back icon only maybe. Use text.
`wizard-footer` overlay can hide content; main padding-bottom 140.

Also scroll-top on step change in component.

Let's write wizard.css.

input.content:
/* ---------- Wizard shell ---------- */
.wizard-screen {
  position: relative;
  min-height: 100dvh;
  background:
    radial-gradient(1100px 700px at 90% -10%, rgba(56, 102, 79, 0.2), transparent 62%),
    radial-gradient(800px 600px at -4% 100%, rgba(176, 138, 87, 0.1), transparent 60%),
    linear-gradient(160deg, #08140f 0%, #050c09 100%);
}

.wizard-screen::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(238, 229, 211, 0.014) 1px, transparent 1px),
    linear-gradient(90deg, rgba(238, 229, 211, 0.014) 1px, transparent 1px);
  background-size: 72px 72px;
  mask-image: radial-gradient(circle at 70% 10%, rgba(0, 0, 0, 0.75), transparent 68%);
}

.wizard-top {
  position: relative;
  z-index: 10;
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem clamp(1rem, 4vw, 2.5rem) 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.wizard-top__actions {
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.wizard-progress {
  position: relative;
  z-index: 5;
  max-width: 1200px;
  margin: 0 auto;
  padding: 1.2rem clamp(1rem, 4vw, 2.5rem) 0.5rem;
}

.wizard-progress__list {
  display: flex;
  align-items: flex-start;
  gap: 0;
}

.wizard-step {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  position: relative;
  color: var(--faint);
  min-width: 0;
}

.wizard-step::after {
  content: '';
  position: absolute;
  top: 14px;
  inset-inline-start: 50%;
  width: 100%;
  height: 1px;
  background: rgba(238, 229, 211, 0.1);
  z-index: -1;
}

.wizard-step:last-child::after {
  display: none;
}

.wizard-step__num {
  width: 29px;
  height: 29px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 0.7rem;
  border: 1px solid rgba(238, 229, 211, 0.16);
  background: #0a1811;
  color: var(--faint);
  transition: all 0.3s var(--ease);
  font-variant-numeric: tabular-nums;
}

.wizard-step__label {
  font-size: 0.64rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}

.wizard-step.is-active {
  color: var(--bronze-light);
}

.wizard-step.is-active .wizard-step__num {
  border-color: rgba(199, 162, 105, 0.7);
  background: linear-gradient(180deg, #d8b985, #b48854);
  color: #10241a;
  box-shadow: 0 0 0 4px rgba(199, 162, 105, 0.09);
  font-weight: 600;
}

.wizard-step.is-done {
  color: var(--sage);
}

.wizard-step.is-done .wizard-step__num {
  border-color: rgba(163, 187, 167, 0.4);
  background: rgba(163, 187, 167, 0.12);
  color: var(--sage);
}

.wizard-step.is-done::after {
  background: linear-gradient(90deg, rgba(163, 187, 167, 0.35), rgba(238, 229, 211, 0.1));
}

.wizard-progress__mobile {
  display: none;
}

.wizard-body {
  position: relative;
  z-index: 3;
  max-width: 1200px;
  margin: 0 auto;
  padding: 1.2rem clamp(1rem, 4vw, 2.5rem) 8.5rem;
}

.step-head {
  margin-bottom: 1.4rem;
  max-width: 760px;
  animation: fadeUp 0.5s var(--ease) both;
}

.step-head h1 {
  font-size: clamp(1.65rem, 3.4vw, 2.35rem);
  margin: 0.45rem 0 0.45rem;
}

.step-head p {
  font-size: 0.84rem;
  line-height: 1.8;
  color: var(--muted);
  max-width: 68ch;
}

.step-content {
  animation: fadeUp 0.5s var(--ease) both;
}

.step-section {
  margin-top: 1.6rem;
}

.step-section__head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.75rem;
}

.step-section__head h2 {
  font-size: 1.02rem;
}

.step-section__head p {
  font-size: 0.72rem;
  color: var(--faint);
  line-height: 1.6;
}

.wizard-footer {
  position: fixed;
  bottom: 0;
  inset-inline: 0;
  z-index: 50;
  padding: 0.7rem clamp(0.75rem, 4vw, 2.5rem) calc(0.8rem + env(safe-area-inset-bottom, 0px));
  background: linear-gradient(to top, rgba(5, 12, 9, 0.96) 16%, rgba(5, 12, 9, 0.72) 62%, transparent 100%);
  pointer-events: none;
}

.wizard-footer__inner {
  pointer-events: auto;
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.55rem 0.65rem;
  border-radius: 18px;
  background: linear-gradient(155deg, rgba(32, 62, 49, 0.82), rgba(9, 24, 17, 0.9));
  border: 1px solid rgba(238, 229, 211, 0.13);
  box-shadow: 0 20px 50px -20px rgba(0, 0, 0, 0.9);
  backdrop-filter: blur(24px) saturate(130%);
}

.wizard-footer__side {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  min-width: 0;
}

.wizard-footer__count {
  font-size: 0.7rem;
  color: var(--faint);
  padding-inline: 0.4rem;
  white-space: nowrap;
}

.wizard-footer__error {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.72rem;
  color: #e0a48d;
  min-width: 0;
  line-height: 1.5;
}

/* ---------- Step 1: world ---------- */
.world-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0.7rem;
}

.world-card {
  grid-column: span 2;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  padding: 1rem;
  min-height: 148px;
  text-align: start;
  border-radius: 18px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background:
    radial-gradient(110% 100% at 100% 0%, rgba(199, 162, 105, 0.045), transparent 48%),
    linear-gradient(155deg, rgba(36, 68, 53, 0.34), rgba(9, 24, 17, 0.62));
  transition: all 0.28s var(--ease);
  overflow: hidden;
}

.world-card:nth-child(1),
.world-card:nth-child(2) {
  grid-column: span 3;
}

.world-card::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(80% 80% at 85% 5%, rgba(255, 250, 238, 0.06), transparent 55%);
  opacity: 0;
  transition: opacity 0.3s;
}

.world-card:hover {
  transform: translateY(-2px);
  border-color: rgba(238, 229, 211, 0.2);
  background:
    radial-gradient(110% 100% at 100% 0%, rgba(199, 162, 105, 0.07), transparent 48%),
    linear-gradient(155deg, rgba(42, 78, 61, 0.42), rgba(10, 27, 19, 0.7));
}

.world-card:hover::after {
  opacity: 1;
}

.world-card.is-active {
  border-color: rgba(199, 162, 105, 0.5);
  box-shadow:
    0 0 0 1px rgba(199, 162, 105, 0.15),
    0 22px 50px -30px rgba(199, 162, 105, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.09);
  background:
    radial-gradient(120% 100% at 100% 0%, rgba(199, 162, 105, 0.12), transparent 52%),
    linear-gradient(155deg, rgba(48, 85, 67, 0.5), rgba(11, 29, 21, 0.75));
}

.world-card__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.2rem;
}

.world-card__icon {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 11px;
  color: var(--wc-accent, var(--sage));
  background: rgba(240, 231, 213, 0.05);
  border: 1px solid rgba(238, 229, 211, 0.1);
}

.world-card.is-active .world-card__icon {
  background: rgba(199, 162, 105, 0.13);
  border-color: rgba(199, 162, 105, 0.3);
  color: var(--bronze-light);
}

.world-card h3 {
  font-size: 0.98rem;
  margin-top: 0.15rem;
}

.world-card__sub {
  font-size: 0.67rem;
  color: var(--wc-accent, var(--bronze));
  opacity: 0.9;
}

.world-card__desc {
  font-size: 0.71rem;
  line-height: 1.65;
  color: var(--muted);
  margin-top: 0.12rem;
}

.world-card__check {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid rgba(238, 229, 211, 0.18);
  display: grid;
  place-items: center;
  flex: none;
  color: transparent;
  transition: all 0.2s;
}

.world-card.is-active .world-card__check {
  background: var(--bronze);
  border-color: var(--bronze);
  color: #10241a;
}

.world-config {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.7rem;
  padding: 1rem;
  border-radius: 18px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background: rgba(4, 13, 9, 0.24);
}

.world-config .field--wide {
  grid-column: span 2;
}

.option-cards {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.45rem;
}

.option-card {
  padding: 0.65rem 0.7rem;
  text-align: start;
  border-radius: 12px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background: rgba(240, 231, 213, 0.025);
  transition: all 0.2s;
}

.option-card:hover {
  border-color: rgba(238, 229, 211, 0.22);
}

.option-card.is-active {
  border-color: rgba(199, 162, 105, 0.42);
  background: rgba(199, 162, 105, 0.09);
}

.option-card strong {
  display: block;
  font-size: 0.77rem;
  font-weight: 500;
}

.option-card small {
  display: block;
  font-size: 0.63rem;
  color: var(--faint);
  line-height: 1.45;
  margin-top: 0.1rem;
}

.scenario-pick-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.6rem;
}

.scenario-mini {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding: 0.8rem 0.85rem;
  border-radius: 14px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background: linear-gradient(150deg, rgba(39, 72, 56, 0.3), rgba(8, 22, 16, 0.55));
  text-align: start;
  transition: all 0.22s;
  min-height: 100px;
}

.scenario-mini:hover {
  border-color: rgba(199, 162, 105, 0.28);
  transform: translateY(-1px);
}

.scenario-mini.is-active {
  border-color: rgba(199, 162, 105, 0.48);
  background: linear-gradient(150deg, rgba(53, 91, 71, 0.42), rgba(10, 28, 20, 0.65));
}

.scenario-mini__year {
  font-size: 0.63rem;
  color: var(--bronze);
  letter-spacing: 0.05em;
}

.scenario-mini strong {
  font-size: 0.85rem;
  font-weight: 500;
}

.scenario-mini small {
  font-size: 0.66rem;
  color: var(--faint);
  line-height: 1.55;
  margin-top: 0.05rem;
}

.difficulty-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.5rem;
}

.difficulty-card {
  padding: 0.7rem 0.75rem;
  text-align: start;
  border-radius: 13px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background: rgba(240, 231, 213, 0.025);
  transition: all 0.22s;
}

.difficulty-card:hover {
  border-color: rgba(238, 229, 211, 0.22);
}

.difficulty-card.is-active {
  border-color: rgba(199, 162, 105, 0.42);
  background: rgba(199, 162, 105, 0.09);
}

.difficulty-card strong {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.78rem;
  font-weight: 500;
}

.difficulty-card strong i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.difficulty-card small {
  display: block;
  color: var(--faint);
  font-size: 0.63rem;
  line-height: 1.5;
  margin-top: 0.15rem;
}

/* ---------- Step 2: country ---------- */
.country-kind-tabs {
  margin-bottom: 1rem;
}

.country-picker {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  grid-template-areas: 'list map';
  gap: 0.8rem;
  align-items: stretch;
}

.country-side {
  grid-area: list;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: 0.8rem;
  border-radius: 18px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background: rgba(5, 15, 10, 0.34);
  min-height: 480px;
}

.country-search {
  position: relative;
}

.country-search svg {
  position: absolute;
  inset-inline-start: 0.75rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--faint);
  pointer-events: none;
}

.country-search input {
  width: 100%;
  min-height: 42px;
  padding-inline: 2.2rem 0.8rem;
  border-radius: 11px;
  border: 1px solid rgba(238, 229, 211, 0.12);
  background: rgba(4, 13, 9, 0.45);
  font-size: 0.82rem;
}

.country-search input:focus {
  outline: none;
  border-color: rgba(199, 162, 105, 0.5);
  box-shadow: 0 0 0 3px rgba(199, 162, 105, 0.08);
}

.region-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.region-chips button {
  padding: 0.2rem 0.55rem;
  border-radius: 99px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  color: var(--muted);
  font-size: 0.64rem;
  transition: all 0.2s;
}

.region-chips button:hover {
  color: var(--ivory);
}

.region-chips button.is-active {
  background: rgba(199, 162, 105, 0.12);
  border-color: rgba(199, 162, 105, 0.32);
  color: var(--bronze-light);
}

.country-list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 400px;
  padding-inline-end: 3px;
  overscroll-behavior: contain;
}

.country-option {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.42rem 0.5rem;
  border-radius: 10px;
  text-align: start;
  border: 1px solid transparent;
  transition: all 0.16s;
}

.country-option:hover {
  background: rgba(240, 231, 213, 0.05);
}

.country-option.is-active {
  background: rgba(199, 162, 105, 0.11);
  border-color: rgba(199, 162, 105, 0.25);
}

.country-option__name {
  display: block;
  font-size: 0.78rem;
  font-weight: 500;
  line-height: 1.4;
}

.country-option__meta {
  display: block;
  font-size: 0.62rem;
  color: var(--faint);
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.country-option__flag {
  width: 30px;
}

.country-map-wrap {
  grid-area: map;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  min-width: 0;
}

.country-map-wrap .world-map {
  flex: 1;
  min-height: 260px;
}

.country-map-wrap .world-map__svg {
  height: 100%;
  object-fit: cover;
}

.selected-country {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.8rem 0.9rem;
  border-radius: 15px;
  border: 1px solid rgba(199, 162, 105, 0.2);
  background: linear-gradient(150deg, rgba(199, 162, 105, 0.07), rgba(8, 22, 16, 0.45));
}

.selected-country .flag {
  width: 52px;
}

.selected-country__text {
  flex: 1;
  min-width: 0;
}

.selected-country__text strong {
  display: block;
  font-size: 0.95rem;
  font-weight: 500;
}

.selected-country__text span {
  display: block;
  font-size: 0.68rem;
  color: var(--faint);
  line-height: 1.55;
}

.country-empty {
  flex: 1;
  min-height: 260px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 1.5rem;
  border-radius: 18px;
  border: 1px dashed rgba(238, 229, 211, 0.14);
  background: rgba(240, 231, 213, 0.015);
  text-align: center;
  color: var(--faint);
  font-size: 0.75rem;
  line-height: 1.7;
}

.country-empty svg {
  color: var(--bronze);
  opacity: 0.7;
}

.fictional-panel {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 1rem;
  padding: 1.3rem;
  border-radius: 22px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background:
    radial-gradient(120% 100% at 100% 0%, rgba(199, 162, 105, 0.08), transparent 50%),
    linear-gradient(150deg, rgba(36, 70, 54, 0.35), rgba(8, 23, 16, 0.62));
}

.fictional-panel__visual {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 260px;
  border-radius: 16px;
  overflow: hidden;
  background:
    radial-gradient(70% 70% at 50% 45%, rgba(199, 162, 105, 0.08), transparent 70%),
    repeating-radial-gradient(circle at 50% 50%, transparent 0 28px, rgba(238, 229, 211, 0.035) 29px 30px);
}

.fictional-panel__visual .flag {
  width: min(260px, 78%);
  transform: rotate(-5deg);
  box-shadow: 0 30px 60px -24px rgba(0, 0, 0, 0.8);
}

.fictional-panel__visual .emblem {
  position: absolute;
  inset-inline-end: 8%;
  bottom: 10%;
  width: 86px;
  height: 86px;
  filter: drop-shadow(0 12px 20px rgba(0, 0, 0, 0.5));
}

.fictional-panel h3 {
  font-size: 1.15rem;
  margin-bottom: 0.4rem;
}

.fictional-panel p {
  font-size: 0.8rem;
  line-height: 1.75;
  color: var(--muted);
}

.fictional-features {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  margin-top: 0.9rem;
}

.fictional-features li {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  font-size: 0.74rem;
  color: var(--ivory-dim);
  line-height: 1.6;
}

.fictional-features svg {
  color: var(--sage);
  flex: none;
  margin-top: 0.22rem;
}

/* ---------- Step 3: identity ---------- */
.identity-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 360px;
  gap: 0.9rem;
  align-items: start;
}

.identity-form {
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
}

.form-section {
  padding: 1rem;
  border-radius: 18px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background: rgba(5, 15, 10, 0.26);
}

.form-section__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.form-section__head h2 {
  font-size: 0.95rem;
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.form-section__head h2 svg {
  color: var(--bronze);
}

.form-section__head span {
  font-size: 0.66rem;
  color: var(--faint);
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem;
}

.form-grid--3 {
  grid-template-columns: repeat(3, 1fr);
}

.form-grid .field--full {
  grid-column: 1 / -1;
}

.identity-options {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.35rem;
}

.identity-option {
  padding: 0.5rem 0.55rem;
  text-align: start;
  border-radius: 10px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background: rgba(240, 231, 213, 0.02);
  transition: all 0.18s;
}

.identity-option:hover {
  border-color: rgba(238, 229, 211, 0.2);
}

.identity-option.is-active {
  border-color: rgba(199, 162, 105, 0.38);
  background: rgba(199, 162, 105, 0.08);
}

.identity-option strong {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.71rem;
  font-weight: 500;
}

.identity-option i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  flex: none;
}

.identity-option small {
  display: none;
}

.language-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.language-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.3rem 0.6rem;
  border-radius: 99px;
  border: 1px solid rgba(238, 229, 211, 0.12);
  color: var(--muted);
  font-size: 0.68rem;
  transition: all 0.18s;
}

.language-chip:hover {
  border-color: rgba(238, 229, 211, 0.28);
  color: var(--ivory);
}

.language-chip.is-active {
  background: rgba(163, 187, 167, 0.12);
  border-color: rgba(163, 187, 167, 0.35);
  color: #c9dcc9;
}

.language-chip svg {
  opacity: 0.65;
}

.custom-add {
  display: flex;
  gap: 0.35rem;
  margin-top: 0.55rem;
}

.custom-add input {
  flex: 1;
  min-width: 0;
  min-height: 36px;
  padding: 0 0.7rem;
  border-radius: 9px;
  border: 1px solid rgba(238, 229, 211, 0.11);
  background: rgba(4, 13, 9, 0.4);
  font-size: 0.74rem;
}

.custom-add input:focus {
  outline: none;
  border-color: rgba(199, 162, 105, 0.45);
}

/* flag designer */
.flag-designer {
  display: grid;
  grid-template-columns: 150px minmax(0, 1fr);
  gap: 0.9rem;
  align-items: start;
}

.flag-designer__preview {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.flag-designer__preview .flag {
  width: 100%;
  border-radius: 11px;
}

.flag-designer__preview span {
  font-size: 0.62rem;
  color: var(--faint);
  text-align: center;
}

.flag-controls {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.control-label {
  font-size: 0.66rem;
  color: var(--faint);
  margin-bottom: 0.25rem;
  display: block;
}

.flag-patterns {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0.3rem;
}

.pattern-btn {
  border-radius: 6px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  overflow: hidden;
  opacity: 0.65;
  transition: all 0.18s;
  aspect-ratio: 4 / 3;
  background: #10241b;
}

.pattern-btn:hover {
  opacity: 1;
}

.pattern-btn.is-active {
  opacity: 1;
  border-color: rgba(199, 162, 105, 0.7);
  box-shadow: 0 0 0 2px rgba(199, 162, 105, 0.16);
}

.pattern-btn svg {
  width: 100%;
  height: 100%;
}

.palette-row {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  flex-wrap: wrap;
}

.palette-row__label {
  font-size: 0.61rem;
  color: var(--faint);
  width: 46px;
  flex: none;
}

.swatch {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid transparent;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.14);
  transition: transform 0.15s;
  flex: none;
}

.swatch:hover {
  transform: scale(1.12);
}

.swatch.is-active {
  border-color: var(--ivory);
  box-shadow: 0 0 0 2px rgba(199, 162, 105, 0.35);
}

.symbol-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0.25rem;
}

.symbol-chip {
  padding: 0.28rem 0.2rem;
  border-radius: 7px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  font-size: 0.6rem;
  color: var(--muted);
  text-align: center;
  transition: all 0.16s;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.symbol-chip:hover {
  color: var(--ivory);
  border-color: rgba(238, 229, 211, 0.2);
}

.symbol-chip.is-active {
  background: rgba(199, 162, 105, 0.1);
  border-color: rgba(199, 162, 105, 0.35);
  color: var(--bronze-light);
}

.emblem-designer {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  gap: 0.8rem;
  align-items: start;
}

.emblem-designer__preview {
  display: grid;
  place-items: center;
  padding: 0.5rem;
  border-radius: 14px;
  background: radial-gradient(circle at 50% 40%, rgba(199, 162, 105, 0.08), transparent 70%);
}

.emblem-designer__preview .emblem {
  width: 74px;
  height: 74px;
}

.emblem-controls {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.emblem-symbols {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.22rem;
}

.emblem-symbols .symbol-chip {
  font-size: 0.57rem;
  padding: 0.22rem 0.1rem;
}

.metal-row {
  display: flex;
  gap: 0.35rem;
}

.metal-chip {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.22rem 0.45rem;
  border-radius: 7px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  font-size: 0.6rem;
  color: var(--muted);
}

.metal-chip i {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex: none;
}

.metal-chip.is-active {
  border-color: rgba(199, 162, 105, 0.4);
  color: var(--ivory);
  background: rgba(199, 162, 105, 0.08);
}

.identity-preview {
  position: sticky;
  top: 1rem;
  border-radius: 22px;
  overflow: hidden;
  border: 1px solid rgba(238, 229, 211, 0.12);
  background:
    radial-gradient(140% 100% at 100% 0%, rgba(199, 162, 105, 0.12), transparent 52%),
    linear-gradient(155deg, rgba(40, 76, 59, 0.5), rgba(7, 21, 14, 0.82));
  box-shadow: var(--shadow-lg);
  backdrop-filter: blur(20px);
}

.identity-preview__flag {
  position: relative;
  padding: 0.8rem 0.8rem 0;
}

.identity-preview__flag .flag {
  width: 100%;
  border-radius: 12px;
  box-shadow: 0 18px 40px -22px rgba(0, 0, 0, 0.8);
}

.identity-preview__body {
  padding: 0.9rem 1rem 1.1rem;
}

.identity-preview__name {
  font-family: 'Alexandria', sans-serif;
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.identity-preview__intl {
  font-size: 0.68rem;
  color: var(--bronze);
  letter-spacing: 0.02em;
  margin-top: 0.1rem;
}

.identity-preview__emblem {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: 0.7rem;
  padding-top: 0.7rem;
  border-top: 1px solid rgba(238, 229, 211, 0.09);
}

.identity-preview__emblem .emblem {
  width: 54px;
  height: 54px;
}

.identity-preview__emblem-text {
  flex: 1;
}

.identity-preview__emblem-text strong {
  display: block;
  font-size: 0.72rem;
  font-weight: 500;
}

.identity-preview__emblem-text span {
  display: block;
  font-size: 0.62rem;
  color: var(--faint);
}

.identity-preview__rows {
  margin-top: 0.65rem;
}

.identity-preview__rows .info-row {
  font-size: 0.7rem;
  padding: 0.34rem 0;
}

.preview-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.6rem;
  color: var(--sage);
  background: rgba(163, 187, 167, 0.09);
  border: 1px solid rgba(163, 187, 167, 0.2);
  padding: 0.15rem 0.45rem;
  border-radius: 99px;
  margin-top: 0.45rem;
}

.preview-note {
  margin-top: 0.7rem;
  font-size: 0.62rem;
  line-height: 1.6;
  color: var(--faint);
  border-top: 1px solid rgba(238, 229, 211, 0.08);
  padding-top: 0.55rem;
}

.territory-area {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
}

.territory-map {
  margin-top: 0.6rem;
}

.territory-map .world-map {
  aspect-ratio: 2.1 / 1;
}

/* ---------- Step 4: government ---------- */
.gov-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.55rem;
}

.gov-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  padding: 0.85rem;
  border-radius: 16px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background: linear-gradient(150deg, rgba(34, 65, 50, 0.28), rgba(8, 22, 15, 0.56));
  text-align: start;
  transition: all 0.22s var(--ease);
  min-height: 152px;
}

.gov-card:hover {
  transform: translateY(-2px);
  border-color: rgba(238, 229, 211, 0.2);
}

.gov-card.is-active {
  border-color: rgba(199, 162, 105, 0.45);
  background:
    radial-gradient(120% 100% at 100% 0%, rgba(199, 162, 105, 0.1), transparent 50%),
    linear-gradient(150deg, rgba(47, 82, 64, 0.42), rgba(10, 27, 19, 0.66));
  box-shadow: 0 18px 42px -28px rgba(199, 162, 105, 0.35);
}

.gov-card__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.gov-card__icon {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: rgba(240, 231, 213, 0.05);
  border: 1px solid rgba(238, 229, 211, 0.1);
  color: var(--gov-accent, var(--sage));
}

.gov-card.is-active .gov-card__icon {
  background: rgba(199, 162, 105, 0.12);
  border-color: rgba(199, 162, 105, 0.28);
  color: var(--bronze-light);
}

.gov-card h3 {
  font-size: 0.9rem;
  font-weight: 500;
}

.gov-card__tag {
  font-size: 0.64rem;
  color: var(--faint);
  margin-top: -0.15rem;
  line-height: 1.5;
}

.gov-card__traits {
  display: flex;
  flex-wrap: wrap;
  gap: 0.2rem;
  margin-top: auto;
  padding-top: 0.2rem;
}

.gov-card__traits span {
  font-size: 0.57rem;
  padding: 0.1rem 0.35rem;
  border-radius: 99px;
  background: rgba(240, 231, 213, 0.045);
  color: var(--faint);
}

.gov-card__diff {
  display: flex;
  gap: 2px;
  flex: none;
}

.gov-card__diff i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(238, 229, 211, 0.15);
}

.gov-card__diff i.on {
  background: var(--bronze);
}

.gov-detail {
  margin-top: 1rem;
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 0.8fr);
  gap: 0.8rem;
}

.gov-detail__panel {
  padding: 1rem;
  border-radius: 18px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background: rgba(5, 15, 10, 0.28);
}

.gov-detail__panel h3 {
  font-size: 0.95rem;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 0.5rem;
}

.gov-structure {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem;
}

.gov-structure__item {
  padding: 0.55rem 0.65rem;
  border-radius: 11px;
  background: rgba(240, 231, 213, 0.03);
  border: 1px solid rgba(238, 229, 211, 0.06);
}

.gov-structure__item span {
  display: block;
  font-size: 0.58rem;
  color: var(--faint);
  margin-bottom: 0.1rem;
}

.gov-structure__item strong {
  display: block;
  font-size: 0.72rem;
  font-weight: 500;
  line-height: 1.5;
}

.gov-future {
  display: flex;
  gap: 0.5rem;
  padding: 0.7rem 0.8rem;
  border-radius: 12px;
  background: rgba(199, 162, 105, 0.07);
  border: 1px solid rgba(199, 162, 105, 0.17);
  font-size: 0.7rem;
  line-height: 1.65;
  color: var(--ivory-dim);
  margin-top: 0.7rem;
}

.gov-future svg {
  color: var(--bronze);
  flex: none;
  margin-top: 0.2rem;
}

.power-grid {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.custom-gov {
  grid-column: 1 / -1;
  margin-top: 0.8rem;
  padding: 1rem;
  border-radius: 18px;
  border: 1px solid rgba(199, 162, 105, 0.2);
  background: rgba(199, 162, 105, 0.04);
}

.custom-gov__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
}

/* ---------- Step 5: conditions ---------- */
.cond-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  flex-wrap: wrap;
  margin-bottom: 0.8rem;
}

.cond-source {
  display: flex;
  gap: 0.5rem;
  align-items: flex-start;
  padding: 0.7rem 0.8rem;
  border-radius: 12px;
  border: 1px solid rgba(199, 162, 105, 0.16);
  background: rgba(199, 162, 105, 0.055);
  font-size: 0.68rem;
  line-height: 1.7;
  color: var(--ivory-dim);
  margin-bottom: 0.8rem;
}

.cond-source svg {
  color: var(--bronze);
  flex: none;
  margin-top: 0.15rem;
}

.quick-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.55rem;
  margin-bottom: 0.8rem;
}

.quick-stat {
  padding: 0.8rem 0.85rem;
  border-radius: 14px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background: linear-gradient(150deg, rgba(39, 72, 56, 0.3), rgba(8, 22, 16, 0.48));
}

.quick-stat__label {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.63rem;
  color: var(--faint);
  line-height: 1.4;
}

.quick-stat__value {
  display: block;
  font-family: 'Alexandria', sans-serif;
  font-size: 1.15rem;
  font-weight: 500;
  margin-top: 0.2rem;
  line-height: 1.4;
  font-variant-numeric: tabular-nums;
}

.quick-stat__sub {
  display: block;
  font-size: 0.6rem;
  color: var(--faint);
  margin-top: 0.05rem;
}

.quick-meters {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem 1.2rem;
  padding: 1rem;
  border-radius: 16px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background: rgba(5, 15, 10, 0.26);
}

.advanced-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.8rem;
}

.advanced-group {
  padding: 0.9rem;
  border-radius: 16px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background: rgba(5, 15, 10, 0.26);
}

.advanced-group h3 {
  font-size: 0.86rem;
  display: flex;
  align-items: center;
  gap: 0.35rem;
  margin-bottom: 0.55rem;
}

.advanced-group h3 svg {
  color: var(--bronze);
}

.advanced-group__fields {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.advanced-group--full {
  grid-column: 1 / -1;
}

.adv-number-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.55rem;
}

.conditions-warning {
  display: flex;
  gap: 0.5rem;
  align-items: flex-start;
  padding: 0.7rem 0.8rem;
  border-radius: 12px;
  background: rgba(192, 132, 104, 0.08);
  border: 1px solid rgba(192, 132, 104, 0.2);
  color: #ddb39e;
  font-size: 0.68rem;
  line-height: 1.65;
  margin-top: 0.7rem;
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .world-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .world-card,
  .world-card:nth-child(1),
  .world-card:nth-child(2) {
    grid-column: span 1;
  }

  .gov-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .identity-layout {
    grid-template-columns: 1fr;
  }

  .identity-preview {
    position: static;
    order: -1;
  }

  .identity-preview__flag {
    max-width: 380px;
  }

  .country-picker {
    grid-template-columns: 1fr;
    grid-template-areas: 'map' 'list';
  }

  .country-side {
    min-height: 0;
  }

  .country-list {
    max-height: 320px;
  }

  .country-map-wrap .world-map {
    min-height: 0;
    aspect-ratio: 2 / 1;
  }
}

@media (max-width: 760px) {
  .wizard-progress__list {
    display: none;
  }

  .wizard-progress {
    padding-top: 0.7rem;
  }

  .wizard-progress__mobile {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.5rem 0.65rem;
    border-radius: 12px;
    border: 1px solid rgba(238, 229, 211, 0.09);
    background: rgba(5, 15, 10, 0.34);
  }

  .wizard-progress__mobile-text {
    font-size: 0.7rem;
    color: var(--muted);
  }

  .wizard-progress__mobile-text strong {
    color: var(--bronze-light);
    font-weight: 500;
  }

  .wizard-dots {
    display: flex;
    gap: 4px;
  }

  .wizard-dots i {
    width: 16px;
    height: 3px;
    border-radius: 99px;
    background: rgba(238, 229, 211, 0.14);
  }

  .wizard-dots i.is-done {
    background: rgba(163, 187, 167, 0.5);
  }

  .wizard-dots i.is-active {
    background: var(--bronze);
  }

  .wizard-body {
    padding-top: 0.9rem;
    padding-bottom: 8rem;
  }

  .world-grid {
    grid-template-columns: 1fr;
  }

  .world-card {
    min-height: 0;
    padding: 0.85rem;
  }

  .world-card__desc {
    font-size: 0.7rem;
  }

  .world-config {
    grid-template-columns: 1fr;
  }

  .world-config .field--wide {
    grid-column: auto;
  }

  .option-cards {
    grid-template-columns: 1fr 1fr;
  }

  .scenario-pick-grid {
    grid-template-columns: 1fr;
  }

  .scenario-mini {
    min-height: 0;
  }

  .difficulty-grid {
    grid-template-columns: 1fr 1fr;
  }

  .fictional-panel {
    grid-template-columns: 1fr;
  }

  .fictional-panel__visual {
    min-height: 190px;
  }

  .flag-designer {
    grid-template-columns: 1fr;
  }

  .flag-designer__preview .flag {
    max-width: 220px;
  }

  .flag-designer__preview span {
    text-align: start;
  }

  .flag-patterns {
    grid-template-columns: repeat(7, 1fr);
  }

  .emblem-designer {
    grid-template-columns: 74px 1fr;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .form-grid--3 {
    grid-template-columns: 1fr;
  }

  .identity-options {
    grid-template-columns: 1fr 1fr;
  }

  .gov-grid {
    grid-template-columns: 1fr;
  }

  .gov-card {
    min-height: 0;
  }

  .gov-detail {
    grid-template-columns: 1fr;
  }

  .custom-gov__grid {
    grid-template-columns: 1fr;
  }

  .quick-summary {
    grid-template-columns: 1fr 1fr;
  }

  .quick-meters {
    grid-template-columns: 1fr;
  }

  .advanced-grid {
    grid-template-columns: 1fr;
  }

  .adv-number-grid {
    grid-template-columns: 1fr;
  }

  .wizard-footer__inner {
    padding: 0.5rem;
    gap: 0.5rem;
  }

  .wizard-footer__count {
    display: none;
  }

  .wizard-footer__error {
    flex: 1;
    font-size: 0.66rem;
  }

  .wizard-footer__side {
    flex: 1;
    justify-content: flex-end;
  }

  .wizard-footer .btn--lg {
    min-height: 46px;
    padding: 0 1rem;
    font-size: 0.85rem;
  }

  .identity-preview__flag {
    max-width: 100%;
  }

  .territory-area {
    grid-template-columns: 1fr;
  }

  .country-map-wrap {
    grid-area: map;
  }

  .country-picker {
    gap: 0.6rem;
  }
}

/* ---------- Game shell ---------- */
.game-shell {
  height: 100dvh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  position: relative;
  background:
    radial-gradient(1000px 640px at 88% -12%, rgba(58, 105, 81, 0.2), transparent 60%),
    radial-gradient(800px 600px at -4% 108%, rgba(176, 138, 87, 0.09), transparent 62%),
    linear-gradient(160deg, #07120d 0%, #040b08 100%);
}

.game-shell::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(238, 229, 211, 0.012) 1px, transparent 1px),
    linear-gradient(90deg, rgba(238, 229, 211, 0.012) 1px, transparent 1px);
  background-size: 80px 80px;
  mask-image: radial-gradient(circle at 70% 0%, rgba(0, 0, 0, 0.6), transparent 65%);
}

.simbar {
  position: relative;
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 0.9rem;
  margin: 0.6rem 0.75rem 0;
  padding: 0.5rem 0.7rem 0.5rem 0.55rem;
  border-radius: 18px;
  flex: none;
  min-height: 66px;
}

.simbar::before {
  background:
    radial-gradient(120% 140% at 85% -40%, rgba(255, 248, 232, 0.1), transparent 50%),
    linear-gradient(100deg, transparent 30%, rgba(255, 255, 255, 0.02) 50%, transparent 64%);
}

.simbar__identity {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  min-width: 0;
  flex: 1;
}

.simbar__identity .flag {
  width: 38px;
}

.simbar__id-text {
  min-width: 0;
}

.simbar__id-text strong {
  display: block;
  font-family: 'Alexandria', sans-serif;
  font-size: 0.92rem;
  font-weight: 600;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 200px;
}

.simbar__id-text span {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.62rem;
  color: var(--faint);
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.simbar__center {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding-inline: 0.85rem;
  border-inline: 1px solid rgba(238, 229, 211, 0.09);
  flex: none;
}

.simbar__date {
  display: flex;
  flex-direction: column;
  gap: 0.05rem;
  min-width: 116px;
  text-align: center;
}

.simbar__date-label {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  font-size: 0.55rem;
  letter-spacing: 0.08em;
  color: var(--faint);
}

.simbar__date strong {
  font-size: 0.79rem;
  font-weight: 500;
  color: var(--ivory);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.play-btn {
  position: relative;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  flex: none;
  color: #11251b;
  background: linear-gradient(180deg, #f4e8d2, #dcc49a);
  border: 1px solid rgba(255, 255, 255, 0.45);
  box-shadow:
    0 8px 20px -8px rgba(199, 162, 105, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.8);
  transition: all 0.22s var(--ease);
}

.play-btn:hover {
  transform: scale(1.04);
  box-shadow: 0 10px 26px -8px rgba(199, 162, 105, 0.7);
}

.play-btn.is-playing {
  background: linear-gradient(180deg, #d9c49e, #c3a270);
}

.play-btn::after {
  content: '';
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid rgba(199, 162, 105, 0.25);
  opacity: 0;
  transition: opacity 0.2s;
}

.play-btn.is-playing::after {
  opacity: 1;
  animation: pulseDot 2.4s ease-in-out infinite;
}

.simbar__speeds .segmented {
  padding: 3px;
  border-radius: 11px;
}

.simbar__speeds .segmented__item {
  min-height: 28px;
  min-width: 27px;
  padding: 0 0.35rem;
  font-size: 0.66rem;
  font-variant-numeric: tabular-nums;
}

.simbar__actions {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  flex: 1;
  justify-content: flex-end;
}

.simbar__notif {
  position: relative;
}

.simbar__badge {
  position: absolute;
  top: 4px;
  inset-inline-end: 4px;
  min-width: 15px;
  height: 15px;
  padding: 0 3px;
  border-radius: 99px;
  background: var(--bronze);
  color: #10241a;
  font-size: 0.52rem;
  font-weight: 600;
  display: grid;
  place-items: center;
  border: 1.5px solid #0b1912;
  line-height: 1;
}

.simbar__save .btn {
  min-height: 38px;
  font-size: 0.78rem;
  border-radius: 10px;
}

.simbar__menu {
  display: none;
}

.game-body {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: stretch;
  position: relative;
  z-index: 2;
}

/* ---------- Rail ---------- */
.game-rail {
  width: 250px;
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 0.85rem 0.6rem 0.8rem;
  overflow-y: auto;
  border-inline-end: 1px solid rgba(238, 229, 211, 0.06);
  background: linear-gradient(180deg, rgba(9, 24, 17, 0.38), rgba(5, 14, 10, 0.2));
  backdrop-filter: blur(8px);
}

.rail-brand {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0 0.4rem 0.35rem;
}

.rail-brand .brand__name {
  font-size: 1rem;
}

.rail-brand .brand__sub {
  font-size: 0.45rem;
}

.rail-world {
  padding: 0.55rem 0.65rem;
  border-radius: 13px;
  border: 1px solid rgba(238, 229, 211, 0.08);
  background: rgba(240, 231, 213, 0.025);
}

.rail-world__label {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.55rem;
  letter-spacing: 0.08em;
  color: var(--faint);
  margin-bottom: 0.15rem;
}

.rail-world strong {
  display: block;
  font-size: 0.72rem;
  font-weight: 500;
  line-height: 1.45;
}

.rail-world span {
  display: block;
  font-size: 0.6rem;
  color: var(--faint);
  line-height: 1.5;
}

.rail-nav {
  display: flex;
  flex-direction: column;
  gap: 1px;
  margin-top: 0.35rem;
}

.rail-link {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  width: 100%;
  padding: 0.52rem 0.55rem;
  border-radius: 10px;
  color: var(--muted);
  text-align: start;
  transition: all 0.2s var(--ease-soft);
  position: relative;
}

.rail-link:hover {
  background: rgba(240, 231, 213, 0.05);
  color: var(--ivory);
}

.rail-link.is-active {
  background: linear-gradient(100deg, rgba(199, 162, 105, 0.13), rgba(199, 162, 105, 0.04));
  color: var(--ivory);
  box-shadow: inset 2px 0 0 var(--bronze);
}

.rail-link.is-active::before {
  content: '';
  position: absolute;
  inset-inline-start: 0;
  top: 20%;
  bottom: 20%;
  width: 2px;
  border-radius: 99px;
  background: var(--bronze);
}

.rail-link__icon {
  display: grid;
  place-items: center;
  flex: none;
  color: var(--sage);
  transition: color 0.2s;
}

.rail-link.is-active .rail-link__icon {
  color: var(--bronze-light);
}

.rail-link__label {
  flex: 1;
  font-size: 0.79rem;
  font-weight: 400;
  line-height: 1.4;
}

.rail-link__chevron {
  color: var(--faint);
  transition: transform 0.2s;
}

.rail-link.is-open .rail-link__chevron {
  transform: rotate(180deg);
}

.rail-sub {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 2px 0 4px;
  margin-inline-start: 1.55rem;
  border-inline-start: 1px solid rgba(238, 229, 211, 0.08);
}

.rail-sub button {
  position: relative;
  padding: 0.26rem 0.65rem;
  text-align: start;
  font-size: 0.67rem;
  color: var(--faint);
  border-radius: 6px;
  transition: all 0.15s;
}

.rail-sub button:hover {
  color: var(--ivory-dim);
  background: rgba(240, 231, 213, 0.04);
}

.rail-sub button.is-active {
  color: var(--bronze-light);
}

.rail-sub button.is-active::before {
  content: '';
  position: absolute;
  inset-inline-start: -1px;
  top: 30%;
  bottom: 30%;
  width: 1px;
  background: var(--bronze);
}

.rail-foot {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  padding-top: 0.6rem;
  border-top: 1px solid rgba(238, 229, 211, 0.07);
}

.rail-foot__row {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.rail-foot__row .btn {
  flex: 1;
  justify-content: flex-start;
  font-size: 0.69rem;
  min-height: 34px;
  padding: 0 0.5rem;
}

.rail-foot__meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0 0.35rem;
  font-size: 0.56rem;
  color: var(--faint);
}

.rail-foot__meta span {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}

/* ---------- Main ---------- */
.game-main {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 1rem clamp(1rem, 2.6vw, 1.8rem) 2.5rem;
  scroll-behavior: smooth;
}

.game-page {
  max-width: 1180px;
  margin: 0 auto;
  animation: fadeUp 0.4s var(--ease) both;
}

.page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 1rem;
}

.page-head__text {
  max-width: 720px;
}

.page-head h1 {
  font-size: clamp(1.45rem, 2.6vw, 1.95rem);
  margin: 0.3rem 0 0.3rem;
}

.page-head p {
  font-size: 0.78rem;
  line-height: 1.75;
  color: var(--muted);
}

.page-head__actions {
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.page-section {
  margin-top: 1rem;
  scroll-margin-top: 1rem;
}

.page-section__head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.55rem;
}

.page-section__head h2 {
  font-size: 1rem;
}

.page-section__head p {
  font-size: 0.68rem;
  color: var(--faint);
}

.panel {
  padding: 1.1rem;
  border-radius: 19px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background:
    radial-gradient(120% 100% at 100% 0%, rgba(199, 162, 105, 0.03), transparent 48%),
    linear-gradient(155deg, rgba(31, 61, 47, 0.3), rgba(7, 20, 14, 0.52));
  backdrop-filter: blur(14px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.panel--flush {
  padding: 0;
  overflow: hidden;
}

.panel__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.panel__head h2,
.panel__head h3 {
  font-size: 0.95rem;
}

.panel__head p {
  font-size: 0.68rem;
  color: var(--faint);
  line-height: 1.6;
  margin-top: 0.15rem;
}

.page-note {
  display: flex;
  gap: 0.5rem;
  align-items: flex-start;
  padding: 0.7rem 0.8rem;
  border-radius: 12px;
  border: 1px solid rgba(199, 162, 105, 0.16);
  background: rgba(199, 162, 105, 0.05);
  font-size: 0.68rem;
  line-height: 1.7;
  color: var(--ivory-dim);
}

.page-note svg {
  color: var(--bronze);
  flex: none;
  margin-top: 0.15rem;
}

.page-note--muted {
  border-color: rgba(238, 229, 211, 0.09);
  background: rgba(240, 231, 213, 0.025);
  color: var(--muted);
}

/* ---------- Mobile dock ---------- */
.mobile-dock {
  display: none;
  position: fixed;
  z-index: 70;
  bottom: calc(0.5rem + env(safe-area-inset-bottom, 0px));
  inset-inline: 0.6rem;
  padding: 0.35rem;
  border-radius: 20px;
  background: linear-gradient(155deg, rgba(29, 57, 44, 0.92), rgba(8, 22, 16, 0.96));
  border: 1px solid rgba(238, 229, 211, 0.13);
  box-shadow: 0 24px 60px -20px rgba(0, 0, 0, 0.9);
  backdrop-filter: blur(26px) saturate(130%);
  grid-template-columns: repeat(4, 1fr);
  gap: 2px;
}

.dock-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.15rem;
  min-height: 48px;
  padding: 0.25rem;
  border-radius: 15px;
  color: var(--faint);
  font-size: 0.58rem;
  transition: all 0.2s;
}

.dock-item.is-active {
  color: var(--bronze-light);
  background: rgba(199, 162, 105, 0.11);
}

.dock-item.is-active svg {
  filter: drop-shadow(0 0 8px rgba(199, 162, 105, 0.35));
}

/* ---------- Notification / more / save lists ---------- */
.notif-list {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.notif-item {
  display: flex;
  gap: 0.7rem;
  padding: 0.75rem;
  border-radius: 13px;
  border: 1px solid rgba(238, 229, 211, 0.07);
  background: rgba(240, 231, 213, 0.02);
}

.notif-item.is-unread {
  border-color: rgba(199, 162, 105, 0.2);
  background: rgba(199, 162, 105, 0.045);
}

.notif-item__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--sage);
  flex: none;
  margin-top: 0.45rem;
}

.notif-item__dot--warning {
  background: var(--clay);
}

.notif-item__dot--world {
  background: var(--bronze);
}

.notif-item__body {
  flex: 1;
  min-width: 0;
}

.notif-item__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.notif-item__head strong {
  font-size: 0.78rem;
  font-weight: 500;
}

.notif-item__head span {
  font-size: 0.6rem;
  color: var(--faint);
  white-space: nowrap;
}

.notif-item p {
  font-size: 0.7rem;
  line-height: 1.65;
  color: var(--muted);
  margin-top: 0.15rem;
}

.notif-empty {
  padding: 2rem 1rem;
  text-align: center;
  color: var(--faint);
  font-size: 0.76rem;
}

.more-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.45rem;
}

.more-nav-item {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  padding: 0.65rem;
  border-radius: 12px;
  border: 1px solid rgba(238, 229, 211, 0.08);
  background: rgba(240, 231, 213, 0.02);
  text-align: start;
  transition: all 0.18s;
}

.more-nav-item:hover {
  border-color: rgba(238, 229, 211, 0.2);
}

.more-nav-item.is-active {
  border-color: rgba(199, 162, 105, 0.35);
  background: rgba(199, 162, 105, 0.07);
}

.more-nav-item__icon {
  color: var(--sage);
  flex: none;
  margin-top: 0.1rem;
}

.more-nav-item strong {
  display: block;
  font-size: 0.76rem;
  font-weight: 500;
  line-height: 1.4;
}

.more-nav-item small {
  display: block;
  font-size: 0.61rem;
  color: var(--faint);
  line-height: 1.4;
  margin-top: 0.05rem;
}

.save-modal__summary {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.7rem;
  border-radius: 13px;
  border: 1px solid rgba(238, 229, 211, 0.08);
  background: rgba(240, 231, 213, 0.025);
  margin-bottom: 0.8rem;
}

.save-modal__summary .flag {
  width: 42px;
}

.save-modal__summary strong {
  display: block;
  font-size: 0.85rem;
  font-weight: 500;
}

.save-modal__summary span {
  display: block;
  font-size: 0.65rem;
  color: var(--faint);
}

.save-modal__note {
  display: flex;
  align-items: flex-start;
  gap: 0.45rem;
  font-size: 0.67rem;
  line-height: 1.6;
  color: var(--faint);
  margin-top: 0.65rem;
}

.sim-note {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.63rem;
  color: var(--faint);
  line-height: 1.5;
}

.sim-note .dot {
  background: var(--bronze);
  width: 5px;
  height: 5px;
  animation: pulseDot 2.4s ease-in-out infinite;
}

/* ---------- Responsive ---------- */
@media (max-width: 980px) {
  .game-rail {
    display: none;
  }

  .mobile-dock {
    display: grid;
  }

  .game-main {
    padding-bottom: 6.5rem;
  }

  .simbar__menu {
    display: inline-flex;
  }
}

@media (max-width: 760px) {
  .simbar {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    grid-template-areas:
      'identity save bell'
      'center center center';
    gap: 0.45rem 0.5rem;
    margin: 0.4rem 0.55rem 0;
    padding: 0.5rem 0.55rem;
    min-height: 0;
    border-radius: 16px;
  }

  .simbar__identity {
    grid-area: identity;
  }

  .simbar__identity .flag {
    width: 33px;
  }

  .simbar__id-text strong {
    font-size: 0.82rem;
    max-width: none;
  }

  .simbar__id-text span {
    font-size: 0.57rem;
  }

  .simbar__actions {
    display: contents;
  }

  .simbar__notif {
    grid-area: bell;
  }

  .simbar__save {
    grid-area: save;
  }

  .simbar__save .btn {
    min-height: 34px;
    padding: 0 0.55rem;
    font-size: 0.7rem;
  }

  .simbar__settings,
  .simbar__exit {
    display: none;
  }

  .simbar__center {
    grid-area: center;
    border: 0;
    padding: 0.15rem 0 0;
    border-top: 1px solid rgba(238, 229, 211, 0.08);
    justify-content: space-between;
    gap: 0.4rem;
  }

  .simbar__date {
    min-width: 0;
    text-align: start;
    flex: 1;
  }

  .simbar__date-label {
    justify-content: flex-start;
  }

  .simbar__date strong {
    font-size: 0.73rem;
  }

  .play-btn {
    width: 36px;
    height: 36px;
  }

  .simbar__speeds .segmented__item {
    min-width: 24px;
    min-height: 26px;
    font-size: 0.6rem;
  }

  .game-main {
    padding: 0.8rem 0.7rem 6.3rem;
  }

  .page-head {
    gap: 0.6rem;
  }

  .page-head h1 {
    font-size: 1.4rem;
  }

  .page-head p {
    font-size: 0.73rem;
  }

  .page-head__actions {
    width: 100%;
  }

  .panel {
    padding: 0.9rem;
  }

  .notif-item {
    padding: 0.65rem;
  }

  .more-grid {
    grid-template-columns: 1fr;
  }

  .rail-foot__row .btn {
    justify-content: center;
  }
}

@media (max-width: 380px) {
  .simbar__id-text span .chip {
    display: none;
  }

  .simbar__save .btn__label {
    display: none;
  }

  .simbar__save .btn {
    width: 36px;
    padding: 0;
  }
}

@media (orientation: landscape) and (max-height: 520px) and (max-width: 980px) {
  .simbar {
    margin-top: 0.3rem;
  }

  .game-main {
    padding-bottom: 5.5rem;
  }

  .mobile-dock {
    bottom: 0.25rem;
  }
}

/* ---------- World page ---------- */
.world-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.32fr) minmax(300px, 0.68fr);
  gap: 0.7rem;
  align-items: stretch;
}

.world-map-panel {
  padding: 0.5rem;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.world-map-panel .world-map {
  flex: 1;
  border-radius: 15px;
  min-height: 400px;
}

.world-map-panel .world-map__svg {
  height: 100%;
  min-height: 400px;
}

.world-map-panel__bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  padding: 0.45rem 0.45rem 0.1rem;
}

.world-map-panel__bar span {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.65rem;
  color: var(--faint);
}

.world-map-panel__bar span strong {
  color: var(--ivory-dim);
  font-weight: 500;
}

.dossier {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  padding: 1rem;
  border-radius: 19px;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background:
    radial-gradient(130% 100% at 100% 0%, rgba(199, 162, 105, 0.07), transparent 50%),
    linear-gradient(155deg, rgba(35, 68, 52, 0.4), rgba(7, 21, 14, 0.68));
  min-width: 0;
}

.dossier__head {
  display: flex;
  align-items: center;
  gap: 0.7rem;
}

.dossier__head .flag {
  width: 58px;
  border-radius: 9px;
}

.dossier__head-text {
  flex: 1;
  min-width: 0;
}

.dossier__head-text h2 {
  font-size: 1.15rem;
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.dossier__head-text span {
  display: block;
  font-size: 0.65rem;
  color: var(--bronze);
  margin-top: 0.15rem;
  line-height: 1.5;
}

.dossier__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
}

.dossier__rows {
  margin-top: 0.15rem;
}

.dossier__rows .info-row {
  font-size: 0.73rem;
  padding: 0.36rem 0;
}

.dossier__neighbors {
  margin-top: auto;
  padding-top: 0.6rem;
  border-top: 1px solid rgba(238, 229, 211, 0.09);
}

.dossier__neighbors-label {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.62rem;
  color: var(--faint);
  margin-bottom: 0.35rem;
}

.neighbor-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
}

.neighbor-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.16rem 0.4rem 0.16rem 0.16rem;
  border-radius: 99px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background: rgba(240, 231, 213, 0.025);
  font-size: 0.6rem;
  color: var(--ivory-dim);
  transition: all 0.16s;
}

.neighbor-chip:hover {
  border-color: rgba(199, 162, 105, 0.3);
}

.neighbor-chip .flag {
  width: 19px;
  border-radius: 3px;
  border-width: 0.5px;
}

.inspect-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.45rem 0.55rem;
  border-radius: 10px;
  background: rgba(199, 162, 105, 0.07);
  border: 1px solid rgba(199, 162, 105, 0.18);
  font-size: 0.64rem;
  color: var(--bronze-light);
}

.inspect-banner button {
  font-size: 0.62rem;
  color: var(--ivory);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.world-facts {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.55rem;
  margin-top: 0.7rem;
}

.fact-card {
  padding: 0.75rem 0.8rem;
  border-radius: 14px;
  border: 1px solid rgba(238, 229, 211, 0.08);
  background: linear-gradient(150deg, rgba(34, 65, 50, 0.24), rgba(7, 20, 14, 0.4));
}

.fact-card__label {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.61rem;
  color: var(--faint);
  line-height: 1.4;
}

.fact-card__value {
  display: block;
  margin-top: 0.2rem;
  font-family: 'Alexandria', sans-serif;
  font-size: 1rem;
  font-weight: 500;
  line-height: 1.4;
  font-variant-numeric: tabular-nums;
}

.fact-card__sub {
  display: block;
  font-size: 0.58rem;
  color: var(--faint);
  line-height: 1.4;
  margin-top: 0.05rem;
}

.world-grid-2 {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
  gap: 0.7rem;
}

.world-config-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.3rem 0.9rem;
}

.world-config-list .info-row {
  font-size: 0.7rem;
}

.next-stage-list {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.next-stage-item {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  padding: 0.5rem 0.6rem;
  border-radius: 10px;
  background: rgba(240, 231, 213, 0.025);
  border: 1px solid rgba(238, 229, 211, 0.06);
  font-size: 0.68rem;
  line-height: 1.55;
  color: var(--muted);
}

.next-stage-item svg {
  color: var(--bronze);
  flex: none;
  margin-top: 0.18rem;
}

/* ---------- Government page ---------- */
.gov-profile {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  gap: 0.7rem;
}

.gov-profile__hero {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  padding: 1.2rem;
  border-radius: 20px;
  overflow: hidden;
  border: 1px solid rgba(238, 229, 211, 0.1);
  background:
    radial-gradient(110% 100% at 100% 0%, rgba(199, 162, 105, 0.1), transparent 52%),
    linear-gradient(155deg, rgba(38, 73, 56, 0.45), rgba(7, 21, 14, 0.7));
}

.gov-profile__hero::after {
  content: '';
  position: absolute;
  inset-inline-end: -10%;
  top: -20%;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(199, 162, 105, 0.07), transparent 68%);
  pointer-events: none;
}

.gov-profile__emblem-row {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.gov-profile__emblem-row .emblem {
  width: 78px;
  height: 78px;
}

.gov-profile__title {
  flex: 1;
  min-width: 0;
}

.gov-profile__title span {
  display: block;
  font-size: 0.6rem;
  letter-spacing: 0.1em;
  color: var(--bronze);
}

.gov-profile__title h2 {
  font-size: 1.4rem;
  margin: 0.1rem 0;
}

.gov-profile__title p {
  font-size: 0.72rem;
  color: var(--muted);
  line-height: 1.55;
}

.gov-profile__desc {
  font-size: 0.76rem;
  line-height: 1.8;
  color: var(--ivory-dim);
}

.gov-profile__traits {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.gov-profile__footer {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-wrap: wrap;
  margin-top: auto;
  padding-top: 0.5rem;
  border-top: 1px solid rgba(238, 229, 211, 0.08);
  font-size: 0.65rem;
  color: var(--faint);
}

.gov-profile__footer .flag {
  width: 22px;
  border-radius: 4px;
}

.gov-power-panel {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  padding: 1.1rem;
}

.gov-power-panel h3 {
  font-size: 0.92rem;
}

.gov-structure-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.45rem;
}

.gov-structure-item {
  padding: 0.6rem 0.65rem;
  border-radius: 11px;
  background: rgba(240, 231, 213, 0.025);
  border: 1px solid rgba(238, 229, 211, 0.06);
}

.gov-structure-item span {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.58rem;
  color: var(--faint);
  margin-bottom: 0.12rem;
}

.gov-structure-item strong {
  display: block;
  font-size: 0.72rem;
  font-weight: 500;
  line-height: 1.5;
}

.gov-future-panel {
  margin-top: 0.7rem;
  display: flex;
  gap: 0.6rem;
  padding: 0.9rem 1rem;
  border-radius: 14px;
  border: 1px solid rgba(199, 162, 105, 0.16);
  background: rgba(199, 162, 105, 0.05);
}

.gov-future-panel svg {
  color: var(--bronze);
  flex: none;
  margin-top: 0.15rem;
}

.gov-future-panel h3 {
  font-size: 0.78rem;
  margin-bottom: 0.15rem;
}

.gov-future-panel p {
  font-size: 0.7rem;
  line-height: 1.7;
  color: var(--muted);
}

/* ---------- Economy / population / infrastructure ---------- */
.stat-cards {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.55rem;
}

.stat-card {
  position: relative;
  padding: 0.9rem;
  border-radius: 16px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background:
    radial-gradient(110% 100% at 100% 0%, rgba(199, 162, 105, 0.04), transparent 55%),
    linear-gradient(150deg, rgba(36, 69, 53, 0.3), rgba(7, 21, 14, 0.5));
  overflow: hidden;
}

.stat-card__icon {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  background: rgba(199, 162, 105, 0.09);
  border: 1px solid rgba(199, 162, 105, 0.18);
  color: var(--bronze-light);
  margin-bottom: 0.45rem;
}

.stat-card__label {
  display: block;
  font-size: 0.63rem;
  color: var(--faint);
  line-height: 1.4;
}

.stat-card__value {
  display: block;
  font-family: 'Alexandria', sans-serif;
  font-size: 1.18rem;
  font-weight: 500;
  line-height: 1.45;
  margin-top: 0.08rem;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}

.stat-card__sub {
  display: block;
  font-size: 0.6rem;
  color: var(--faint);
  margin-top: 0.1rem;
  line-height: 1.45;
}

.stat-card--wide {
  grid-column: span 2;
}

.opening-banner {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.6rem 0.8rem;
  margin-bottom: 0.7rem;
  border-radius: 12px;
  border: 1px solid rgba(163, 187, 167, 0.18);
  background: rgba(163, 187, 167, 0.055);
}

.opening-banner__icon {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  background: rgba(163, 187, 167, 0.1);
  color: var(--sage);
  flex: none;
}

.opening-banner strong {
  display: block;
  font-size: 0.72rem;
  font-weight: 500;
}

.opening-banner span {
  display: block;
  font-size: 0.62rem;
  color: var(--faint);
  line-height: 1.5;
}

.sector-meters {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem 1.3rem;
}

.population-hero {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 0.7rem;
}

.population-big {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 1.2rem;
  border-radius: 19px;
  border: 1px solid rgba(238, 229, 211, 0.09);
  background:
    radial-gradient(100% 120% at 100% 0%, rgba(163, 187, 167, 0.08), transparent 55%),
    linear-gradient(150deg, rgba(35, 68, 52, 0.35), rgba(7, 20, 14, 0.55));
}

.population-big__label {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.65rem;
  color: var(--faint);
}

.population-big__value {
  font-family: 'Alexandria', sans-serif;
  font-size: clamp(2.2rem, 5vw, 3.4rem);
  font-weight: 600;
  line-height: 1.15;
  margin: 0.25rem 0 0.1rem;
  font-variant-numeric: tabular-nums;
  color: var(--ivory);
}

.population-big__value small {
  font-size: 0.9rem;
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-weight: 400;
  color: var(--muted);
  margin-inline-start: 0.35rem;
}

.population-big__note {
  font-size: 0.7rem;
  color: var(--muted);
  line-height: 1.6;
}

.population-facts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.45rem;
}

.timezone-row,
.identity-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0;
  border-bottom: 1px solid rgba(238, 229, 211, 0.07);
  font-size: 0.72rem;
}

.timezone-row:last-child,
.identity-row:last-child {
  border-bottom: 0;
}

.identity-row__icon {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: rgba(240, 231, 213, 0.04);
  display: grid;
  place-items: center;
  color: var(--sage);
  flex: none;
}

.identity-row__text {
  flex: 1;
  min-width: 0;
}

.identity-row__text span {
  display: block;
  font-size: 0.6rem;
  color: var(--faint);
}

.identity-row__text strong {
  display: block;
  font-size: 0.74rem;
  font-weight: 500;
}

.lang-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
}

/* ---------- Projects ---------- */
.roadmap-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.55rem;
}

.roadmap-card {
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
  padding: 0.85rem;
  border-radius: 15px;
  border: 1px solid rgba(238, 229, 211, 0.08);
  background: rgba(240, 231, 213, 0.02);
  opacity: 0.82;
}

.roadmap-card__icon {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  background: rgba(240, 231, 213, 0.04);
  border: 1px solid rgba(238, 229, 211, 0.08);
  color: var(--sage);
  flex: none;
}

.roadmap-card__text {
  flex: 1;
  min-width: 0;
}

.roadmap-card h3 {
  font-size: 0.8rem;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-wrap: wrap;
}

.roadmap-card p {
  font-size: 0.67rem;
  line-height: 1.6;
  color: var(--faint);
  margin-top: 0.12rem;
}

.roadmap-card .chip {
  font-size: 0.55rem;
  padding: 0.08rem 0.4rem;
}

/* ---------- Statistics ---------- */
.reference-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem;
}

.ref-item {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.55rem 0.65rem;
  border-radius: 9px;
  background: rgba(240, 231, 213, 0.02);
  border: 1px solid rgba(238, 229, 211, 0.05);
  font-size: 0.71rem;
}

.ref-item span {
  color: var(--faint);
}

.ref-item strong {
  font-weight: 500;
  text-align: end;
  font-variant-numeric: tabular-nums;
}

.status-list {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.status-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.45rem 0;
  border-bottom: 1px solid rgba(238, 229, 211, 0.07);
  font-size: 0.71rem;
}

.status-row:last-child {
  border-bottom: 0;
}

.status-row span {
  color: var(--faint);
}

.status-row strong {
  margin-inline-start: auto;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--sage);
  flex: none;
}

.status-dot--pending {
  background: var(--bronze);
}

.status-dot--off {
  background: rgba(238, 229, 211, 0.2);
}

/* ---------- Events ---------- */
.event-timeline {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.event-timeline::before {
  content: '';
  position: absolute;
  top: 12px;
  bottom: 12px;
  inset-inline-start: 6px;
  width: 1px;
  background: linear-gradient(180deg, rgba(199, 162, 105, 0.35), rgba(238, 229, 211, 0.08));
}

.event-row {
  position: relative;
  display: flex;
  gap: 0.8rem;
  padding: 0.65rem 0 0.8rem;
}

.event-row__dot {
  width: 13px;
  height: 13px;
  border-radius: 50%;
  border: 2px solid #0a1a12;
  background: var(--sage);
  flex: none;
  margin-top: 0.22rem;
  box-shadow: 0 0 0 1px rgba(163, 187, 167, 0.2);
  z-index: 1;
}

.event-row__dot--bronze {
  background: var(--bronze);
  box-shadow: 0 0 0 1px rgba(199, 162, 105, 0.3);
}

.event-row__dot--clay {
  background: var(--clay);
}

.event-row__body {
  flex: 1;
  min-width: 0;
}

.event-row__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
}

.event-row__head strong {
  font-size: 0.78rem;
  font-weight: 500;
}

.event-row__head span {
  font-size: 0.6rem;
  color: var(--faint);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.event-row__body p {
  font-size: 0.69rem;
  line-height: 1.7;
  color: var(--muted);
  margin-top: 0.12rem;
}

.event-row__tag {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.56rem;
  color: var(--faint);
  margin-top: 0.28rem;
}

/* ---------- Responsive ---------- */
@media (max-width: 1100px) {
  .world-hero {
    grid-template-columns: 1fr;
  }

  .world-map-panel .world-map,
  .world-map-panel .world-map__svg {
    min-height: 320px;
  }

  .world-facts {
    grid-template-columns: 1fr 1fr;
  }

  .stat-cards {
    grid-template-columns: 1fr 1fr;
  }

  .population-hero,
  .gov-profile {
    grid-template-columns: 1fr;
  }

  .world-grid-2 {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .world-map-panel .world-map,
  .world-map-panel .world-map__svg {
    min-height: 240px;
  }

  .world-map-panel__bar {
    padding: 0.2rem 0.1rem 0.25rem;
  }

  .world-map-panel__bar span:last-child {
    display: none;
  }

  .world-facts {
    gap: 0.4rem;
  }

  .fact-card {
    padding: 0.6rem;
  }

  .fact-card__value {
    font-size: 0.9rem;
  }

  .stat-cards {
    grid-template-columns: 1fr 1fr;
    gap: 0.4rem;
  }

  .stat-card {
    padding: 0.72rem;
  }

  .stat-card__value {
    font-size: 1rem;
  }

  .stat-card--wide {
    grid-column: span 2;
  }

  .sector-meters {
    grid-template-columns: 1fr;
  }

  .world-config-list {
    grid-template-columns: 1fr;
  }

  .gov-structure-grid {
    grid-template-columns: 1fr;
  }

  .roadmap-grid {
    grid-template-columns: 1fr;
  }

  .reference-grid {
    grid-template-columns: 1fr;
  }

  .population-facts {
    grid-template-columns: 1fr;
  }

  .population-big__value {
    font-size: 2.1rem;
  }

  .event-row__head {
    flex-direction: column;
    gap: 0.05rem;
  }
}

