459:   font-variant-numeric: tabular-nums;
460:   overflow-wrap: anywhere;
461: }
462: 
463: .stat-card__sub {
464:   display: block;
465:   font-size: 0.6rem;
466:   color: var(--faint);
467:   margin-top: 0.1rem;
468:   line-height: 1.45;
469: }
470: 
471: .stat-card--wide {
472:   grid-column: span 2;
473: }
474: 
475: .opening-banner {
476:   display: flex;
477:   align-items: center;
478:   gap: 0.6rem;
479:   padding: 0.6rem 0.8rem;
480:   margin-bottom: 0.7rem;
481:   border-radius: 12px;
482:   border: 1px solid rgba(163, 187, 167, 0.18);
483:   background: rgba(163, 187, 167, 0.055);
484: }
485: 
486: .opening-banner__icon {
487:   width: 30px;
488:   height: 30px;
489:   border-radius: 9px;
490:   display: grid;
491:   place-items: center;
492:   background: rgba(163, 187, 167, 0.1);
493:   color: var(--sage);
494:   flex: none;
495: }
496: 
497: .opening-banner strong {
498:   display: block;
499:   font-size: 0.72rem;
500:   font-weight: 500;
501: }
502: 
503: .opening-banner span {
504:   display: block;
505:   font-size: 0.62rem;
506:   color: var(--faint);
507:   line-height: 1.5;
508: }
509: 
510: .sector-meters {
511:   display: grid;
512:   grid-template-columns: 1fr 1fr;
513:   gap: 0.65rem 1.3rem;
514: }
515: 
516: .population-hero {
517:   display: grid;
518:   grid-template-columns: 1.1fr 0.9fr;
519:   gap: 0.7rem;
520: }
521: 
522: .population-big {
523:   display: flex;
524:   flex-direction: column;
525:   justify-content: center;
526:   padding: 1.2rem;
527:   border-radius: 19px;
528:   border: 1px solid rgba(238, 229, 211, 0.09);
529:   background:
530:     radial-gradient(100% 120% at 100% 0%, rgba(163, 187, 167, 0.08), transparent 55%),
531:     linear-gradient(150deg, rgba(35, 68, 52, 0.35), rgba(7, 20, 14, 0.55));
532: }
533: 
534: .population-big__label {
535:   display: flex;
536:   align-items: center;
537:   gap: 0.35rem;
538:   font-size: 0.65rem;
539:   color: var(--faint);
540: }
541: 
542: .population-big__value {
543:   font-family: 'Alexandria', sans-serif;
544:   font-size: clamp(2.2rem, 5vw, 3.4rem);
545:   font-weight: 600;
546:   line-height: 1.15;
547:   margin: 0.25rem 0 0.1rem;
548:   font-variant-numeric: tabular-nums;
549:   color: var(--ivory);
550: }
551: 
552: .population-big__value small {
553:   font-size: 0.9rem;
554:   font-family: 'IBM Plex Sans Arabic', sans-serif;
555:   font-weight: 400;
556:   color: var(--muted);
557:   margin-inline-start: 0.35rem;
558: }
559: 
560: .population-big__note {
561:   font-size: 0.7rem;
562:   color: var(--muted);
563:   line-height: 1.6;
564: }
565: 
566: .population-facts {
567:   display: grid;
568:   grid-template-columns: 1fr 1fr;
569:   gap: 0.45rem;
570: }
571: 
572: .timezone-row,
573: .identity-row {
574:   display: flex;
575:   align-items: center;
576:   gap: 0.5rem;
577:   padding: 0.5rem 0;
578:   border-bottom: 1px solid rgba(238, 229, 211, 0.07);
579:   font-size: 0.72rem;
580: }
581: 
582: .timezone-row:last-child,
583: .identity-row:last-child {
584:   border-bottom: 0;
585: }
586: 
587: .identity-row__icon {
588:   width: 28px;
589:   height: 28px;
590:   border-radius: 8px;
591:   background: rgba(240, 231, 213, 0.04);
592:   display: grid;
593:   place-items: center;
594:   color: var(--sage);
595:   flex: none;
596: }
597: 
598: .identity-row__text {
599:   flex: 1;
600:   min-width: 0;
601: }
602: 
603: .identity-row__text span {
604:   display: block;
605:   font-size: 0.6rem;
606:   color: var(--faint);
607: }
608: 
609: .identity-row__text strong {
610:   display: block;
611:   font-size: 0.74rem;
612:   font-weight: 500;
613: }
614: 
615: .lang-list {
616:   display: flex;
617:   flex-wrap: wrap;
618:   gap: 0.25rem;
619: }
620: 
621: /* ---------- Projects ---------- */
622: .roadmap-grid {
623:   display: grid;
624:   grid-template-columns: 1fr 1fr;
625:   gap: 0.55rem;
626: }
627: 
628: .roadmap-card {
629:   display: flex;
630:   align-items: flex-start;
631:   gap: 0.7rem;
632:   padding: 0.85rem;
633:   border-radius: 15px;
634:   border: 1px solid rgba(238, 229, 211, 0.08);
635:   background: rgba(240, 231, 213, 0.02);
636:   opacity: 0.82;
637: }
638: 
639: .roadmap-card__icon {
640:   width: 34px;
641:   height: 34px;
642:   border-radius: 9px;
643:   display: grid;
644:   place-items: center;
645:   background: rgba(240, 231, 213, 0.04);
646:   border: 1px solid rgba(238, 229, 211, 0.08);
647:   color: var(--sage);
648:   flex: none;
649: }
650: 
651: .roadmap-card__text {
652:   flex: 1;
653:   min-width: 0;
654: }
655: 
656: .roadmap-card h3 {
657:   font-size: 0.8rem;
658:   display: flex;
659:   align-items: center;
660:   gap: 0.4rem;
661:   flex-wrap: wrap;
662: }
663: 
664: .roadmap-card p {
665:   font-size: 0.67rem;
666:   line-height: 1.6;
667:   color: var(--faint);
668:   margin-top: 0.12rem;
669: }
670: 
671: .roadmap-card .chip {
672:   font-size: 0.55rem;
673:   padding: 0.08rem 0.4rem;
674: }
675: 
676: /* ---------- Statistics ---------- */
677: .reference-grid {
678:   display: grid;
679:   grid-template-columns: 1fr 1fr;
680:   gap: 0.5rem;
681: }
682: 
683: .ref-item {
684:   display: flex;
685:   align-items: baseline;
686:   justify-content: space-between;
687:   gap: 0.75rem;
688:   padding: 0.55rem 0.65rem;
689:   border-radius: 9px;
690:   background: rgba(240, 231, 213, 0.02);
691:   border: 1px solid rgba(238, 229, 211, 0.05);
692:   font-size: 0.71rem;
693: }
694: 
695: .ref-item span {
696:   color: var(--faint);
697: }
698: 
699: .ref-item strong {
700:   font-weight: 500;
701:   text-align: end;
702:   font-variant-numeric: tabular-nums;
703: }
704: 
705: .status-list {
706:   display: flex;
707:   flex-direction: column;
708:   gap: 0.1rem;
709: }
710: 
711: .status-row {
712:   display: flex;
713:   align-items: center;
714:   gap: 0.5rem;
715:   padding: 0.45rem 0;
716:   border-bottom: 1px solid rgba(238, 229, 211, 0.07);
717:   font-size: 0.71rem;
718: }
719: 
720: .status-row:last-child {
721:   border-bottom: 0;
722: }
723: 
724: .status-row span {
725:   color: var(--faint);
726: }
727: 
728: .status-row strong {
729:   margin-inline-start: auto;
730:   font-weight: 500;
731:   font-variant-numeric: tabular-nums;
732: }
733: 
734: .status-dot {
735:   width: 7px;
736:   height: 7px;
737:   border-radius: 50%;
738:   background: var(--sage);
739:   flex: none;
740: }
741: 
742: .status-dot--pending {
743:   background: var(--bronze);
744: }
745: 
746: .status-dot--off {
747:   background: rgba(238, 229, 211, 0.2);
748: }
749: 
750: /* ---------- Events ---------- */
751: .event-timeline {
752:   position: relative;
753:   display: flex;
754:   flex-direction: column;
755:   gap: 0;
756: }
757: 
758: .event-timeline::before {
759:   content: '';
760:   position: absolute;
761:   top: 12px;
762:   bottom: 12px;
763:   inset-inline-start: 6px;
764:   width: 1px;
765:   background: linear-gradient(180deg, rgba(199, 162, 105, 0.35), rgba(238, 229, 211, 0.08));
766: }
767: 
768: .event-row {
769:   position: relative;
770:   display: flex;
771:   gap: 0.8rem;
772:   padding: 0.65rem 0 0.8rem;
773: }
774: 
775: .event-row__dot {
776:   width: 13px;
777:   height: 13px;
778:   border-radius: 50%;
779:   border: 2px solid #0a1a12;
780:   background: var(--sage);
781:   flex: none;
782:   margin-top: 0.22rem;
783:   box-shadow: 0 0 0 1px rgba(163, 187, 167, 0.2);
784:   z-index: 1;
785: }
786: 
787: .event-row__dot--bronze {
788:   background: var(--bronze);
789:   box-shadow: 0 0 0 1px rgba(199, 162, 105, 0.3);
790: }
791: 
792: .event-row__dot--clay {
793:   background: var(--clay);
794: }
795: 
796: .event-row__body {
797:   flex: 1;
798:   min-width: 0;
799: }
800: 
801: .event-row__head {
802:   display: flex;
803:   align-items: baseline;
804:   justify-content: space-between;
805:   gap: 0.6rem;
806: }
807: 
808: .event-row__head strong {
809:   font-size: 0.78rem;
810:   font-weight: 500;
811: }
812: 
813: .event-row__head span {
814:   font-size: 0.6rem;
815:   color: var(--faint);
816:   font-variant-numeric: tabular-nums;
817:   white-space: nowrap;
818: }
819: 
820: .event-row__body p {
821:   font-size: 0.69rem;
822:   line-height: 1.7;
823:   color: var(--muted);
824:   margin-top: 0.12rem;
825: }
826: 
827: .event-row__tag {
828:   display: inline-flex;
829:   align-items: center;
830:   gap: 0.25rem;
831:   font-size: 0.56rem;
832:   color: var(--faint);
833:   margin-top: 0.28rem;
834: }
835: 
836: /* ---------- Responsive ---------- */
837: @media (max-width: 1100px) {
838:   .world-hero {
839:     grid-template-columns: 1fr;
840:   }
841: 
842:   .world-map-panel .world-map,
843:   .world-map-panel .world-map__svg {
844:     min-height: 320px;
845:   }
846: 
847:   .world-facts {
848:     grid-template-columns: 1fr 1fr;
849:   }
850: 
851:   .stat-cards {
852:     grid-template-columns: 1fr 1fr;
853:   }
854: 
855:   .population-hero,
856:   .gov-profile {
857:     grid-template-columns: 1fr;
858:   }
859: 
860:   .world-grid-2 {
861:     grid-template-columns: 1fr;
862:   }
863: }
864: 
865: @media (max-width: 760px) {
866:   .world-map-panel .world-map,
867:   .world-map-panel .world-map__svg {
868:     min-height: 240px;
869:   }
870: 
871:   .world-map-panel__bar {
872:     padding: 0.2rem 0.1rem 0.25rem;
873:   }
874: 
875:   .world-map-panel__bar span:last-child {
876:     display: none;
877:   }
878: 
879:   .world-facts {
880:     gap: 0.4rem;
881:   }
882: 
883:   .fact-card {
884:     padding: 0.6rem;
885:   }
886: 
887:   .fact-card__value {
888:     font-size: 0.9rem;
889:   }
890: 
891:   .stat-cards {
892:     grid-template-columns: 1fr 1fr;
893:     gap: 0.4rem;
894:   }
895: 
896:   .stat-card {
897:     padding: 0.72rem;
898:   }
899: 
900:   .stat-card__value {
901:     font-size: 1rem;
902:   }
903: 
904:   .stat-card--wide {
905:     grid-column: span 2;
906:   }
907: 
908:   .sector-meters {
909:     grid-template-columns: 1fr;
910:   }
911: 
912:   .world-config-list {
913:     grid-template-columns: 1fr;
914:   }
915: 
916:   .gov-structure-grid {
917:     grid-template-columns: 1fr;
918:   }
919: 
920:   .roadmap-grid {
921:     grid-template-columns: 1fr;
922:   }
923: 
924:   .reference-grid {
925:     grid-template-columns: 1fr;
926:   }
927: 
928:   .population-facts {
929:     grid-template-columns: 1fr;
930:   }
931: 
932:   .population-big__value {
933:     font-size: 2.1rem;
934:   }
935: 
936:   .event-row__head {
937:     flex-direction: column;
938:     gap: 0.05rem;
939:   }
940: }

