117:       return { ok: false, message: 'اختر سيناريو حديثاً للمتابعة.' }
118:     }
119:     if (!draft.world.name.trim()) {
120:       return { ok: false, message: 'أدخل اسماً للعالم.' }
121:     }
122:     return { ok: true }
123:   }
124:   if (step === 2) {
125:     if (draft.countryKind === 'real' && !draft.selectedCode) {
126:       return { ok: false, message: 'اختر دولة من الخريطة أو القائمة.' }
127:     }
128:     return { ok: true }
129:   }
130:   if (step === 3) {
131:     const id = draft.identity
132:     if (!id.nameAr.trim()) return { ok: false, message: 'أدخل اسم الدولة بالعربية.' }
133:     if (!id.nameIntl.trim()) return { ok: false, message: 'أدخل الاسم الدولي للدولة.' }
134:     if (!id.capitalAr.trim()) return { ok: false, message: 'أدخل اسم العاصمة.' }
135:     if (!id.languages.length) return { ok: false, message: 'اختر لغة وطنية واحدة على الأقل.' }
136:     if (!id.currencyName.trim()) return { ok: false, message: 'أدخل اسم العملة.' }
137:     if (!id.identity) return { ok: false, message: 'اختر الهوية الوطنية.' }
138:     if (id.identity === 'custom' && !id.identityCustom.trim()) {
139:       return { ok: false, message: 'اكتب وصف الهوية المخصصة.' }
140:     }
141:     return { ok: true }
142:   }
143:   if (step === 4) {
144:     if (!draft.government.id) return { ok: false, message: 'اختر نظام الحكم.' }
145:     if (draft.government.id === 'custom' && !draft.government.customName.trim()) {
146:       return { ok: false, message: 'أدخل اسماً للنظام المخصص.' }
147:     }
148:     return { ok: true }
149:   }
150:   if (step === 5) {
151:     const c = draft.conditions
152:     if (!Number.isFinite(c.population) || c.population < 1000) {
153:       return { ok: false, message: 'أدخل عدد سكان صالحاً (ألف نسمة على الأقل).' }
154:     }
155:     if (!Number.isFinite(c.treasury) || c.treasury < 0) {
156:       return { ok: false, message: 'أدخل قيمة خزينة صالحة.' }
157:     }
158:     return { ok: true }
159:   }
160:   return { ok: true }
161: }
