  const name = identity.nameAr.trim() || 'دولة بلا اسم'
  const govName = governmentDisplayName(draft.government)
  return {
    version: 1,
    id,
    slotId: null,
    createdAt: now,
    updatedAt: now,
    world: { ...draft.world },
    country: identity,
    government: { ...draft.government },
