90: ): { state: GameState; record: SaveRecord } | null {
91:   const saves = loadSaves()
92:   const targetId = slotId ?? state.slotId
93:   const now = Date.now()
94:   const existingIndex = saves.findIndex((s) => s.meta.id === targetId)
95:   const existing = existingIndex >= 0 ? saves[existingIndex] : null
96:   const nextState: GameState = {
97:     ...state,
98:     updatedAt: now,
99:     slotId: targetId ?? null,
100:   }
101:   const meta = buildSaveMeta(
102:     targetId ? { ...nextState, slotId: targetId } : nextState,
103:     name.trim() || existing?.meta.name || `${state.country.nameAr} — ${formatGameDate(state.calendar)}`,
104:   )
105:   if (targetId) meta.id = targetId
106:   else nextState.slotId = meta.id
107:   meta.updatedAt = now
108:   const record: SaveRecord = { meta, state: nextState }
109:   if (existingIndex >= 0) {
110:     meta.createdAt = saves[existingIndex].meta.createdAt
111:     saves[existingIndex] = record
112:   } else {
113:     saves.unshift(record)
114:   }
115:   saves.sort((a, b) => b.meta.updatedAt - a.meta.updatedAt)
116:   const trimmed = saves.slice(0, MAX_SAVES)
117:   if (!writeJSON(SAVES_KEY, trimmed)) return null
118:   setActiveSave(nextState)
119:   return { state: nextState, record }
120: }
