import { ABUNDANCE_LEVELS, DIFFICULTY_BY_ID } from '../data/worlds'

export { DIFFICULTY_BY_ID }

export const WORLDS_ABUNDANCE_LABEL = Object.fromEntries(
  ABUNDANCE_LEVELS.map((level) => [level.id, level.label]),
) as Record<(typeof ABUNDANCE_LEVELS)[number]['id'], string>

import { useEffect, useState } from 'react'
import { Brand } from '../../components/Logo'
import { useGame } from '../../game/GameProvider'
import { applyScenario } from '../../game/draft'
import { buildGameState, newDraft, validateStep } from '../../game/setup'
import type { WizardDraft } from '../../game/setup'
import type { WorldKind } from '../../game/types'
import { Button } from '../../components/ui/Controls'
import { StepHead, WizardFooter, WizardProgress } from './parts'
import { WorldStep } from './steps/WorldStep'
import { CountryStep } from './steps/CountryStep'
import { IdentityStep } from './steps/IdentityStep'
import { GovernmentStep } from './steps/GovernmentStep'
import { ConditionsStep } from './steps/ConditionsStep'

export function WizardScreen({
  seed,
  scenarioId,
  onExit,
  onStarted,
}: {
  seed?: WorldKind | null
  scenarioId?: string | null
  onExit: () => void
  onStarted: () => void
}) {
  const { createGame } = useGame()
  const [draft, setDraft] = useState<WizardDraft>(() => {
    let next = newDraft(seed ? undefined : undefined)
    if (seed) {
      const { defaultWorld } = requireWorlds()
      next = newDraft(defaultWorld(seed))
    }
    if (scenarioId) next = applyScenario(next, scenarioId)
    return next
  })
  const [error, setError] = useState<string | null>(null)

  useEffect(() => setError(null), [draft.step])

  const next = () => {
    const result = validateStep(draft.step, draft)
    if (!result.ok) {
      setError(result.message ?? 'أكمل البيانات المطلوبة.')
      return
    }
    if (draft.step < 5) {
      setDraft((current) => ({ ...current, step: (current.step + 1) as 2 | 3 | 4 | 5 }))
      return
    }
    createGame(buildGameState(draft))
    onStarted()
  }

  const back = () => {
    if (draft.step > 1) {
      setDraft((current) => ({ ...current, step: (current.step - 1) as 1 | 2 | 3 | 4 }))
    } else onExit()
  }

  return (
    <div className="wizard-screen">
      <header className="wizard-top">
        <Brand compact />
        <div className="wizard-top__actions">
          <Button variant="glass" size="sm" onClick={onExit}>إلغاء</Button>
        </div>
      </header>
      <WizardProgress step={draft.step} />
      <main className="wizard-main">
        <StepHead step={draft.step} />
        {draft.step === 1 && <WorldStep draft={draft} setDraft={setDraft} />}
        {draft.step === 2 && <CountryStep draft={draft} setDraft={setDraft} />}
        {draft.step === 3 && <IdentityStep draft={draft} setDraft={setDraft} />}
        {draft.step === 4 && <GovernmentStep draft={draft} setDraft={setDraft} />}
        {draft.step === 5 && <ConditionsStep draft={draft} setDraft={setDraft} />}
      </main>
      <WizardFooter
        step={draft.step}
        error={error}
        onBack={back}
        onNext={next}
        onExit={onExit}
      />
    </div>
  )
}

function requireWorlds() {
  return {
    defaultWorld: (kind: WorldKind) => {
      const kindDefault = {
        real: 'العالم الحقيقي', fictional: 'عالم جديد', custom: 'عالم جديد', historical: 'عالم تاريخي', modern: 'العالم الحديث',
      }[kind]
      return {
        kind,
        name: kindDefault,
        year: kind === 'historical' ? 1945 : 2026,
        eraLabel: kind === 'historical' ? 'سيناريو تاريخي' : 'الحاضر',
        techLevel: 'high' as const,
        abundance: 'balanced' as const,
        climate: 'varied' as const,
        difficulty: 'balanced' as const,
        scenarioId: null,
        notes: '',
      }
    },
  }
}

import { useEffect, useState } from 'react'
import { MainMenu } from './screens/MainMenu'
import { WizardScreen } from './screens/wizard/WizardScreen'
import { GameScreen } from './screens/GameScreen'
import { ScenariosScreen } from './screens/ScenariosScreen'
import { SavesScreen } from './screens/SavesScreen'
import { SettingsScreen } from './screens/SettingsScreen'
import { useGame } from './game/GameProvider'
import { storageAvailableFlag } from './game/storage'
import type { WorldKind } from './game/types'

type Screen = 'menu' | 'wizard' | 'game' | 'scenarios' | 'saves' | 'settings'

export default function App() {
  const { game, loadSave, continueLatest } = useGame()
  const [screen, setScreen] = useState<Screen>('menu')
  const [seed, setSeed] = useState<WorldKind | null>(null)
  const [scenarioId, setScenarioId] = useState<string | null>(null)

  useEffect(() => {
    document.documentElement.lang = 'ar'
    document.documentElement.dir = 'rtl'
  }, [])

  const backToMenu = () => {
    setSeed(null)
    setScenarioId(null)
    setScreen('menu')
  }

  const startWizard = (kind: WorldKind | null = null) => {
    setSeed(kind)
    setScenarioId(null)
    setScreen('wizard')
  }

  const startScenario = (id: string) => {
    setScenarioId(id)
    setSeed(null)
    setScreen('wizard')
  }

  const continueGame = () => {
    if (continueLatest()) setScreen('game')
  }

  const loadGame = (id: string) => {
    if (loadSave(id)) setScreen('game')
  }

  if (screen === 'wizard') {
    return (
      <WizardScreen
        seed={seed}
        scenarioId={scenarioId}
        onExit={backToMenu}
        onStarted={() => setScreen('game')}
      />
    )
  }

  if (screen === 'game' && game) {
    return <GameScreen onExit={backToMenu} onSettings={() => setScreen('settings')} />
  }

  if (screen === 'scenarios') {
    return <ScenariosScreen onBack={backToMenu} onStart={startScenario} />
  }

  if (screen === 'saves') {
    return (
      <SavesScreen
        onBack={backToMenu}
        onLoad={loadGame}
        onNewGame={() => startWizard(null)}
        storageAvailable={storageAvailableFlag}
      />
    )
  }

  if (screen === 'settings') {
    return (
      <SettingsScreen
        onBack={() => setScreen(game ? 'game' : 'menu')}
        onOpenSaves={() => setScreen('saves')}
      />
    )
  }

  return (
    <MainMenu
      onNewGame={startWizard}
      onContinue={continueGame}
      onSaves={() => setScreen('saves')}
      onScenarios={() => setScreen('scenarios')}
      onSettings={() => setScreen('settings')}
    />
  )
}
